/* KHBD Mĩ thuật Lớp 5 KNTT — Bút Xanh, tích hợp NLS+AI (mức Cơ bản, GV kiểm soát) */
window.KHO_DATA_L5_MITHUAT = [
{"lop":5,"mon":"Mĩ thuật","tuan":1,"tiet":1,"bai":"Chủ đề 1: Yếu tố tạo hình trong thực hành, sáng tạo theo chủ đề (Tiết 1 - Quan sát, nhận biết)","yccd":"1. Năng lực mĩ thuật\n- Quan sát, nhận biết được vẻ đẹp tạo hình, hình ảnh, chất liệu liên quan đến chủ đề.\n- Nêu được cảm nhận ban đầu về đối tượng thẩm mĩ của chủ đề.\n- Có ý thức khai thác hình ảnh, chất liệu để chuẩn bị cho thực hành sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu thích cái đẹp, có ý thức tìm tòi, sáng tạo trong học tập.\n- Chăm chỉ, cẩn thận, giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 1.1 CB2b: Tìm được dữ liệu, thông tin và nội dung thông qua tìm kiếm đơn giản trong môi trường số: HS chọn được từ khoá phù hợp và tìm được tư liệu đúng yếu tố tạo hình cần.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề yếu tố tạo hình trong thực hành, sáng tạo theo chủ đề.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (quan sát, nhận biết).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Quan sát, nhận biết","gv":"- GV cho HS quan sát hình minh hoạ trong SGK Mĩ thuật 5 và tư liệu GV chuẩn bị thêm về chủ đề yếu tố tạo hình trong thực hành, sáng tạo theo chủ đề.\n- GV đặt câu hỏi gợi mở để HS nhận ra hình ảnh, chất liệu, cách thể hiện đặc trưng của chủ đề.\n- GV tóm tắt, bổ sung, khắc sâu nội dung Em có biết trong SGK.","hs":"- HS quan sát hình, tư liệu và trả lời câu hỏi.\n- HS nêu hiểu biết, cảm nhận ban đầu về chủ đề.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập - Chia sẻ hiểu biết","gv":"- GV cho HS kể thêm những hình ảnh, tác phẩm cùng chủ đề mà em biết.\n- GV định hướng HS lựa chọn hình ảnh sẽ khai thác cho phần thực hành ở tiết sau.","hs":"- HS chia sẻ trước lớp.\n- HS lựa chọn ý tưởng, hình ảnh cho sản phẩm của mình."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (quan sát, nhận biết).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS tìm tư liệu cho chủ đề của mình trong kho ảnh và bảo tàng số GV chỉ định; GV hướng dẫn cách chọn từ khoá theo yếu tố tạo hình như chấm, nét, hình, khối, màu, đậm nhạt thay vì tìm chung chung, và cách đọc phần chú thích để biết ảnh của ai.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS lập phiếu tư liệu gồm ba hình đã chọn, mỗi hình ghi yếu tố tạo hình nổi bật và nguồn ảnh.\n⚠ (Miền 4: An toàn) Chỉ tìm trong các trang GV đã chỉ định, không tự vào trang lạ, không tải tệp không rõ nguồn; ảnh đưa vào phiếu phải ghi tên tác giả hoặc tên trang, thiếu nguồn thì không dùng.","hs":"- HS chọn được từ khoá phù hợp và tìm được tư liệu đúng yếu tố tạo hình cần.\n- HS lập được phiếu tư liệu có ghi nguồn đầy đủ."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 1, Tiết 1 - Quan sát, nhận biết"},
{"lop":5,"mon":"Mĩ thuật","tuan":2,"tiet":2,"bai":"Chủ đề 1: Yếu tố tạo hình trong thực hành, sáng tạo theo chủ đề (Tiết 2 - Cách thực hiện sản phẩm)","yccd":"1. Năng lực mĩ thuật\n- Nêu được các bước cơ bản để thể hiện chủ đề thành sản phẩm mĩ thuật.\n- Lựa chọn được hình ảnh, chất liệu, cách thể hiện phù hợp với khả năng.\n- Biết vận dụng yếu tố và nguyên lí tạo hình đã học vào sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu thích cái đẹp, có ý thức tìm tòi, sáng tạo trong học tập.\n- Chăm chỉ, cẩn thận, giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 3.1 CB2a: Xác định được các cách tạo và chỉnh sửa nội dung đơn giản ở các định dạng đơn giản: HS phác được nhiều phương án bố cục bằng ứng dụng vẽ và biết hoàn tác khi cần.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề yếu tố tạo hình trong thực hành, sáng tạo theo chủ đề.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (tìm hiểu cách thực hiện).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Cách thực hiện","gv":"- GV hướng dẫn HS phân tích các bước thực hiện sản phẩm trong SGK Mĩ thuật 5 (khai thác nội dung chủ đề yếu tố tạo hình trong thực hành, sáng tạo theo chủ đề).\n- GV làm mẫu hoặc mời HS lên thao tác thử một số bước; lưu ý cách chọn hình ảnh, chất liệu phù hợp.","hs":"- HS quan sát, phân tích các bước thực hiện.\n- HS nêu lại các bước và ghi nhớ."},{"ten":"3. Luyện tập - Thử phác ý tưởng","gv":"- GV cho HS phác nhanh ý tưởng, bố cục cho sản phẩm của mình.\n- GV quan sát, gợi ý điều chỉnh để HS chuẩn bị tốt cho tiết thực hành.","hs":"- HS phác ý tưởng, lựa chọn cách thể hiện.\n- HS chuẩn bị chất liệu phù hợp."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (tìm hiểu cách thực hiện).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) HS dùng ứng dụng vẽ đơn giản trên máy của lớp để phác vài phương án bố cục cho sản phẩm: thử đổi vị trí mảng chính, đổi tỉ lệ, hoàn tác khi chưa ưng; vẽ trên máy cho phép thử nhiều phương án trong thời gian ngắn, việc mà phác trên giấy tốn nhiều thời gian hơn.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS chọn một phương án, nói rõ vì sao bỏ các phương án còn lại rồi chuyển sang thể hiện sản phẩm bằng chất liệu thật.\n⚠ (Miền 4: An toàn) HS lưu bản phác vào thư mục mang tên mình, không mở và sửa bài của bạn; bản phác trên máy chỉ là bước chuẩn bị, sản phẩm cuối cùng vẫn do HS thể hiện bằng tay.","hs":"- HS phác được nhiều phương án bố cục bằng ứng dụng vẽ và biết hoàn tác khi cần.\n- HS chọn và bảo vệ được phương án bố cục của mình."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 1, Tiết 2 - Cách thực hiện sản phẩm"},
{"lop":5,"mon":"Mĩ thuật","tuan":3,"tiet":3,"bai":"Chủ đề 1: Yếu tố tạo hình trong thực hành, sáng tạo theo chủ đề (Tiết 3 - Thực hành, sáng tạo)","yccd":"1. Năng lực mĩ thuật\n- Tạo được sản phẩm mĩ thuật thể hiện nội dung chủ đề theo ý thích.\n- Vận dụng được hình, mảng, màu sắc, đậm nhạt, không gian để làm rõ nội dung.\n- Bước đầu thể hiện được sự sáng tạo và dấu ấn cá nhân trong sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu thích cái đẹp, có ý thức tìm tòi, sáng tạo trong học tập.\n- Chăm chỉ, cẩn thận, giữ vệ sinh khi thực hành.","dodung":"- GV: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; 2-3 sản phẩm mẫu ở các mức độ khác nhau; bảng tiêu chí nhận xét sản phẩm viết sẵn; sao giấy màu cho HS bình chọn; nam châm, băng dính giấy để trưng bày; máy tính, máy chiếu và học liệu số.\n- HS: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; bút chì, tẩy, màu vẽ, giấy vẽ A4, giấy màu, kéo, keo dán, đất nặn.\n- Vật liệu thay thế khi lớp thiếu đồ dùng: giấy báo cũ, bìa carton, vỏ hộp sữa, lá cây khô, hột hạt, dây len, vải vụn, cúc áo, ống hút đã rửa sạch; đất nặn có thể thay bằng bột mì trộn muối và màu thực phẩm.\n- An toàn: dùng kéo đầu tròn, chuyền kéo quay mũi về phía mình; dao rọc giấy chỉ dùng khi có GV bên cạnh; keo, màu không đưa lên miệng; hết giờ thu gom giấy vụn, lau bàn, rửa tay.","hoatdong":[{"ten":"1. Khởi động","gv":"- (3 phút) GV chiếu 4 mảnh cắt ra từ tranh, hỏi: \"Mảnh này nổi bật yếu tố nào: chấm, nét, hình mảng hay màu sắc?\".\n- GV hỏi thêm: \"Mảng nào đậm nhất, mảng nào nhạt nhất?\" (dự kiến: HS chỉ mảng nền tối là đậm, mảng bầu trời là nhạt).\n- GV dẫn vào tiết học: các em sẽ hoàn thành sản phẩm từ ý tưởng đã phác ở tiết trước.","hs":"- HS gọi tên yếu tố tạo hình nhận ra ở mỗi mảnh tranh.\n- HS chỉ được mảng đậm, mảng nhạt trong tranh.\n- HS nêu nhiệm vụ tiết học, bày đồ dùng lên bàn."},{"ten":"2. Khám phá - Nhắc lại yêu cầu","gv":"- (7 phút) GV cho HS xem 3 sản phẩm mẫu (vẽ màu, xé dán giấy, ghép vật liệu tái sử dụng) và hỏi: \"Đâu là hình ảnh chính, đặt ở đâu, to hay nhỏ?\".\n- Dự kiến HS đáp: hình chính ở khoảng giữa, vẽ to và rõ; hình phụ nhỏ hơn, ở phía sau; nền tối làm nổi hình sáng.\n- GV chốt 4 lưu ý: hình chính to và rõ; thêm 2-3 hình phụ tạo xa - gần; màu có đậm có nhạt; chừa khoảng trống, không lấp kín mặt giấy.\n- GV treo bảng tiêu chí nhận xét, đọc to để HS biết trước đích cần đạt.","hs":"- HS quan sát, so sánh 3 sản phẩm mẫu và trả lời câu hỏi.\n- HS chỉ ra hình ảnh chính, hình ảnh phụ ở từng mẫu.\n- HS nhắc lại 4 lưu ý bằng lời của mình.\n- HS đọc thầm bảng tiêu chí, hình dung bài mình sẽ làm."},{"ten":"3. Luyện tập - Thực hành, sáng tạo","gv":"- (17 phút) GV giao việc: mỗi HS làm một sản phẩm theo chủ đề; nhóm 2-4 HS có thể ghép các bài thành một bức lớn.\n- GV ghi các bước lên bảng: 1) phác bố cục bằng nét chì mờ, chia mảng chính - phụ; 2) vẽ hoặc cắt hình chính; 3) thêm hình phụ và nền; 4) tô màu mảng lớn trước; 5) tạo đậm nhạt; 6) tẩy nét thừa, kí tên.\n- GV làm mẫu chậm bước 5: tô một mảng theo ba mức đậm - vừa - nhạt, ấn bút mạnh dần; nếu xé dán thì chọn ba sắc độ giấy khác nhau.\n- GV đến từng bàn, hỏi HS còn lúng túng \"Em muốn kể điều gì trong bài này?\"; nhắc dùng kéo, keo an toàn.","hs":"- HS chọn chất liệu phù hợp và làm bài theo 6 bước.\n- HS phác bố cục nhẹ tay, làm rõ hình ảnh chính trước.\n- HS thử ba mức đậm nhạt ra giấy nháp rồi mới làm vào bài.\n- HS giúp bạn trong nhóm, giữ an toàn khi dùng kéo, keo."},{"ten":"4. Trưng bày, nhận xét sản phẩm","gv":"- (6 phút) GV cho các nhóm dán bài lên bảng nhóm, tạo phòng tranh mini ở góc lớp.\n- GV nêu tiêu chí: 1) có hình ảnh chính rõ, đúng chủ đề; 2) bố cục cân đối; 3) màu hài hoà, có đậm nhạt; 4) bài sạch sẽ, có ý tưởng riêng.\n- GV cho HS tự đánh giá theo tiêu chí, sau đó đi xem bài bạn, dán một sao giấy vào bài mình thích và nói \"Mình thích bài này vì...\"; GV nhận xét 2-3 bài.","hs":"- HS trưng bày sản phẩm ngay ngắn theo vị trí nhóm.\n- HS đối chiếu bài mình với 4 tiêu chí, tự đánh dấu mức đạt.\n- HS dán sao, nói câu nhận xét và giới thiệu bài của mình."},{"ten":"5. Vận dụng - Củng cố, dặn dò","gv":"- (2 phút) GV hỏi: em đã dùng hình, mảng, màu sắc, đậm nhạt thế nào để làm rõ nội dung chủ đề?\n- GV gợi ý dùng sản phẩm trang trí góc học tập, làm bìa vở hoặc tặng người thân.\n- GV nhận xét tiết học, nhắc thu giấy vụn, lau bàn, rửa tay; dặn tiết sau mang màu vẽ và tranh ảnh sưu tầm cho chủ đề mới.","hs":"- HS nhắc lại các yếu tố tạo hình đã vận dụng.\n- HS nêu nơi sẽ trưng bày sản phẩm của mình.\n- HS dọn chỗ ngồi, rửa tay và ghi nhớ đồ dùng tiết sau."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 1, Tiết 3 - Thực hành, sáng tạo"},
{"lop":5,"mon":"Mĩ thuật","tuan":4,"tiet":4,"bai":"Chủ đề 1: Yếu tố tạo hình trong thực hành, sáng tạo theo chủ đề (Tiết 4 - Trưng bày, thảo luận và vận dụng)","yccd":"1. Năng lực mĩ thuật\n- Trưng bày, giới thiệu và nêu được cảm nhận về sản phẩm của mình và của bạn.\n- Phân tích được vẻ đẹp, ý nghĩa của sản phẩm theo yếu tố, nguyên lí tạo hình.\n- Biết vận dụng kết quả học tập vào trang trí, làm đẹp cuộc sống.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu thích cái đẹp, có ý thức tìm tòi, sáng tạo trong học tập.\n- Chăm chỉ, cẩn thận, giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 3.2 CB2a: Chọn được các cách sửa đổi, tinh chỉnh, cải thiện và tích hợp các mục đơn giản có nội dung và thông tin mới để tạo ra những nội dung và thông tin mới và độc đáo: HS hoàn thiện được phần giới thiệu sản phẩm trên trang trưng bày của lớp.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề yếu tố tạo hình trong thực hành, sáng tạo theo chủ đề.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (trưng bày, thảo luận và vận dụng).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Chuẩn bị trưng bày","gv":"- GV hướng dẫn HS hoàn thiện, sắp xếp sản phẩm để trưng bày (theo cá nhân/nhóm).\n- GV gợi ý cách giới thiệu, nêu ý tưởng và cảm nhận về sản phẩm.","hs":"- HS hoàn thiện, sắp xếp sản phẩm.\n- HS chuẩn bị lời giới thiệu về sản phẩm của mình."},{"ten":"3. Luyện tập - Trưng bày, thảo luận","gv":"- GV tổ chức cho HS trưng bày, giới thiệu sản phẩm; gợi mở để HS phân tích, thảo luận về vẻ đẹp, ý nghĩa của sản phẩm.\n- GV nhận xét, đánh giá, ghi nhận sự tiến bộ và sáng tạo của HS.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS thảo luận, nhận xét sản phẩm của mình và của bạn."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV gợi ý HS vận dụng sản phẩm, kiến thức của chủ đề yếu tố tạo hình trong thực hành, sáng tạo theo chủ đề vào trang trí, làm đẹp góc học tập, lớp học hoặc cuộc sống.\n- GV hệ thống nội dung chủ đề, nhận xét tiết học, tuyên dương; dặn HS chuẩn bị cho chủ đề sau.","hs":"- HS nêu cách vận dụng sản phẩm vào cuộc sống.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) HS chụp sản phẩm và đưa vào trang trưng bày của lớp kèm tên tác phẩm, tên tác giả và một câu nêu yếu tố tạo hình mình đã dùng làm điểm nhấn.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 2) HS nhận xét sản phẩm của bạn theo đúng tiêu chí đã học về yếu tố tạo hình nổi bật, bố cục và màu sắc, nói lời góp ý xây dựng thay vì khen chung chung.\n⚠ (Miền 4: An toàn) Ghi đủ tên tác giả cho từng sản phẩm và nguồn cho mọi tư liệu tham khảo; trang trưng bày chia sẻ trong lớp, muốn đưa ra ngoài phải hỏi ý kiến các bạn có sản phẩm trong đó.","hs":"- HS hoàn thiện được phần giới thiệu sản phẩm trên trang trưng bày của lớp.\n- HS nhận xét bạn theo tiêu chí cụ thể, có góp ý xây dựng."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 1, Tiết 4 - Trưng bày, thảo luận và vận dụng"},
{"lop":5,"mon":"Mĩ thuật","tuan":5,"tiet":5,"bai":"Chủ đề 2: Hình tượng anh hùng dân tộc trong mĩ thuật tạo hình Việt Nam (Tiết 1 - Quan sát, nhận biết)","yccd":"1. Năng lực mĩ thuật\n- Quan sát, nhận biết được vẻ đẹp tạo hình, hình ảnh, chất liệu liên quan đến chủ đề.\n- Nêu được cảm nhận ban đầu về đối tượng thẩm mĩ của chủ đề.\n- Có ý thức khai thác hình ảnh, chất liệu để chuẩn bị cho thực hành sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu quý, tự hào về truyền thống anh hùng và lịch sử dân tộc.\n- Chăm chỉ, có trách nhiệm khi hoàn thành nhiệm vụ học tập.\n4. Tích hợp\n- Năng lực số 1.3 CB2a: Xác định được cách tổ chức, lưu trữ và truy xuất dữ liệu, thông tin và nội dung một cách đơn giản trong môi trường số: HS đối chiếu được hai nguồn tư liệu trước khi thể hiện nhân vật lịch sử.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề hình tượng anh hùng dân tộc trong mĩ thuật tạo hình Việt Nam.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (quan sát, nhận biết).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Quan sát, nhận biết","gv":"- GV cho HS quan sát hình minh hoạ trong SGK Mĩ thuật 5 và tư liệu GV chuẩn bị thêm về chủ đề hình tượng anh hùng dân tộc trong mĩ thuật tạo hình Việt Nam.\n- GV đặt câu hỏi gợi mở để HS nhận ra hình ảnh, chất liệu, cách thể hiện đặc trưng của chủ đề.\n- GV tóm tắt, bổ sung, khắc sâu nội dung Em có biết trong SGK.","hs":"- HS quan sát hình, tư liệu và trả lời câu hỏi.\n- HS nêu hiểu biết, cảm nhận ban đầu về chủ đề.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập - Chia sẻ hiểu biết","gv":"- GV cho HS kể thêm những hình ảnh, tác phẩm cùng chủ đề mà em biết.\n- GV định hướng HS lựa chọn hình ảnh sẽ khai thác cho phần thực hành ở tiết sau.","hs":"- HS chia sẻ trước lớp.\n- HS lựa chọn ý tưởng, hình ảnh cho sản phẩm của mình."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (quan sát, nhận biết).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS tìm hiểu về một anh hùng dân tộc qua tư liệu số ở trang của bảo tàng và thư viện tỉnh: tượng đài, tranh chân dung, hiện vật; đối chiếu ít nhất hai nguồn về niên đại và chi tiết trang phục, vũ khí trước khi đưa vào bài vẽ.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS ghi vào phiếu tên nhân vật, chi tiết tạo hình đặc trưng và tên hai nguồn đã đối chiếu.\n⚠ (Miền 4: An toàn) Thông tin lịch sử phải lấy từ bảo tàng, sách giáo khoa hoặc trang của cơ quan nhà nước; nhiều hình vẽ nhân vật lịch sử trên mạng là do người ta tưởng tượng hoặc do máy tạo, không đúng sử liệu nên không dùng làm căn cứ.","hs":"- HS đối chiếu được hai nguồn tư liệu trước khi thể hiện nhân vật lịch sử.\n- HS ghi được nguồn và chi tiết tạo hình đặc trưng của nhân vật."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 2, Tiết 1 - Quan sát, nhận biết"},
{"lop":5,"mon":"Mĩ thuật","tuan":6,"tiet":6,"bai":"Chủ đề 2: Hình tượng anh hùng dân tộc trong mĩ thuật tạo hình Việt Nam (Tiết 2 - Cách thực hiện sản phẩm)","yccd":"1. Năng lực mĩ thuật\n- Nêu được các bước cơ bản để thể hiện chủ đề thành sản phẩm mĩ thuật.\n- Lựa chọn được hình ảnh, chất liệu, cách thể hiện phù hợp với khả năng.\n- Biết vận dụng yếu tố và nguyên lí tạo hình đã học vào sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu quý, tự hào về truyền thống anh hùng và lịch sử dân tộc.\n- Chăm chỉ, có trách nhiệm khi hoàn thành nhiệm vụ học tập.\n4. Tích hợp\n- Năng lực số 1.1 CB2c: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nắm được tư thế và tỉ lệ dáng nhân vật nhờ xem tượng từ nhiều góc.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề hình tượng anh hùng dân tộc trong mĩ thuật tạo hình Việt Nam.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (tìm hiểu cách thực hiện).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Cách thực hiện","gv":"- GV hướng dẫn HS phân tích các bước thực hiện sản phẩm trong SGK Mĩ thuật 5 (khai thác nội dung chủ đề hình tượng anh hùng dân tộc trong mĩ thuật tạo hình Việt Nam).\n- GV làm mẫu hoặc mời HS lên thao tác thử một số bước; lưu ý cách chọn hình ảnh, chất liệu phù hợp.","hs":"- HS quan sát, phân tích các bước thực hiện.\n- HS nêu lại các bước và ghi nhớ."},{"ten":"3. Luyện tập - Thử phác ý tưởng","gv":"- GV cho HS phác nhanh ý tưởng, bố cục cho sản phẩm của mình.\n- GV quan sát, gợi ý điều chỉnh để HS chuẩn bị tốt cho tiết thực hành.","hs":"- HS phác ý tưởng, lựa chọn cách thể hiện.\n- HS chuẩn bị chất liệu phù hợp."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (tìm hiểu cách thực hiện).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS xem tượng đài anh hùng dân tộc chụp từ nhiều góc và ở chế độ xoay ba chiều nếu bảo tàng số có sẵn; nhờ đó thấy được tư thế, hướng nhìn và tỉ lệ dáng người mà một bức ảnh chính diện không diễn tả hết.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS phác dáng nhân vật theo tư thế mình chọn, dùng ảnh chụp từ góc tương ứng để kiểm tra lại tỉ lệ đầu, thân, chân rồi sửa chỗ chưa cân đối.\n⚠ (Miền 4: An toàn) HS thao tác trên máy dùng chung, mở đúng trang GV giao và đóng lại sau khi dùng; hình ảnh tượng đài là tư liệu di sản nên khi dùng phải ghi rõ tên tác phẩm và tác giả.","hs":"- HS nắm được tư thế và tỉ lệ dáng nhân vật nhờ xem tượng từ nhiều góc.\n- HS tự kiểm tra và sửa được tỉ lệ trong bài phác của mình."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 2, Tiết 2 - Cách thực hiện sản phẩm"},
{"lop":5,"mon":"Mĩ thuật","tuan":7,"tiet":7,"bai":"Chủ đề 2: Hình tượng anh hùng dân tộc trong mĩ thuật tạo hình Việt Nam (Tiết 3 - Thực hành, sáng tạo)","yccd":"1. Năng lực mĩ thuật\n- Tạo được sản phẩm mĩ thuật thể hiện nội dung chủ đề theo ý thích.\n- Vận dụng được hình, mảng, màu sắc, đậm nhạt, không gian để làm rõ nội dung.\n- Bước đầu thể hiện được sự sáng tạo và dấu ấn cá nhân trong sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu quý, tự hào về truyền thống anh hùng và lịch sử dân tộc.\n- Chăm chỉ, có trách nhiệm khi hoàn thành nhiệm vụ học tập.","dodung":"- GV: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; 2-3 sản phẩm mẫu ở các mức độ khác nhau; bảng tiêu chí nhận xét sản phẩm viết sẵn; sao giấy màu cho HS bình chọn; nam châm, băng dính giấy để trưng bày; máy tính, máy chiếu và học liệu số.\n- HS: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; bút chì, tẩy, màu vẽ, giấy vẽ A4, giấy màu, kéo, keo dán, đất nặn.\n- Vật liệu thay thế khi lớp thiếu đồ dùng: giấy báo cũ, bìa carton, vỏ hộp sữa, lá cây khô, hột hạt, dây len, vải vụn, cúc áo, ống hút đã rửa sạch; đất nặn có thể thay bằng bột mì trộn muối và màu thực phẩm.\n- An toàn: dùng kéo đầu tròn, chuyền kéo quay mũi về phía mình; dao rọc giấy chỉ dùng khi có GV bên cạnh; keo, màu không đưa lên miệng; hết giờ thu gom giấy vụn, lau bàn, rửa tay.","hoatdong":[{"ten":"1. Khởi động","gv":"- (3 phút) GV chiếu 4 hình tượng đài, tranh chân dung và tổ chức trò chơi Đoán tên anh hùng dân tộc.\n- GV hỏi: \"Nhìn tư thế, trang phục, em đoán nhân vật đang làm gì?\" (dự kiến: cưỡi voi ra trận, giương cờ, cầm gươm chỉ huy).\n- GV dẫn vào bài: tiết này các em hoàn thành sản phẩm về người anh hùng mình đã chọn.","hs":"- HS quan sát, nêu tên nhân vật lịch sử nhận ra.\n- HS mô tả tư thế, trang phục, đồ vật đi kèm.\n- HS nhắc lại nhiệm vụ và bày đồ dùng lên bàn."},{"ten":"2. Khám phá - Nhắc lại yêu cầu","gv":"- (7 phút) GV cho HS xem lại sản phẩm mẫu và hỏi: \"Chi tiết nào giúp người xem nhận ra đó là anh hùng dân tộc?\".\n- Dự kiến HS đáp: mũ, áo giáp, cờ, gươm, ngựa hoặc voi; dáng người vươn cao, khoẻ khoắn.\n- GV chốt: dáng nhân vật là hình chính, vẽ to ở giữa tranh; thêm cờ, mây, núi làm nền; màu nhân vật tươi sáng nổi trên nền trầm.\n- GV treo bảng tiêu chí nhận xét sản phẩm để HS biết trước đích cần đạt.","hs":"- HS quan sát mẫu và nêu chi tiết giúp nhận biết nhân vật.\n- HS nêu chất liệu định dùng cho bài của mình.\n- HS nhắc lại lưu ý về bố cục và màu sắc.\n- HS đọc thầm bảng tiêu chí nhận xét."},{"ten":"3. Luyện tập - Thực hành, sáng tạo","gv":"- (17 phút) GV giao việc: mỗi HS vẽ, xé dán hoặc nặn hình tượng một anh hùng dân tộc; nhóm 2-4 HS có thể ghép thành tranh đề tài chung.\n- GV ghi các bước: 1) phác dáng nhân vật bằng nét chì mờ; 2) thêm chi tiết trang phục, vũ khí; 3) vẽ nền và hình phụ; 4) tô màu mảng lớn trước; 5) làm đậm nền cho nổi nhân vật; 6) hoàn thiện, kí tên.\n- GV làm mẫu chậm bước 1: phác ba nét trục đầu - thân - chân để giữ đúng tỉ lệ người trước khi vẽ chi tiết.\n- GV gợi ý HS thiếu đồ dùng dùng giấy báo, bìa carton, vải vụn làm áo giáp, cờ; nhắc an toàn khi cắt dán.","hs":"- HS chọn nhân vật và chất liệu phù hợp với đồ dùng có sẵn.\n- HS phác dáng theo nét trục, giữ tỉ lệ người cân đối.\n- HS thêm chi tiết trang phục, vũ khí cho rõ nhân vật.\n- HS làm đậm nền để nhân vật nổi bật, giữ an toàn khi cắt dán."},{"ten":"4. Trưng bày, nhận xét sản phẩm","gv":"- (6 phút) GV cho HS gắn bài lên bảng nhóm theo tên nhân vật, tạo phòng tranh mini Anh hùng dân tộc ở góc lớp.\n- GV nêu tiêu chí: 1) nhận ra được nhân vật; 2) bố cục cân đối, nhân vật là hình chính; 3) màu hài hoà, có đậm nhạt; 4) bài sạch, có ý tưởng riêng.\n- GV cho HS tự đánh giá, đi xem và dán sao vào bài mình thích, nói \"Mình thích bài này vì...\"; GV nhận xét 2-3 bài theo tiêu chí.","hs":"- HS trưng bày bài theo nhóm nhân vật.\n- HS tự đối chiếu bài mình với 4 tiêu chí.\n- HS dán sao, nhận xét bài bạn và giới thiệu bài của mình."},{"ten":"5. Vận dụng - Củng cố, dặn dò","gv":"- (2 phút) GV hỏi: em học được điều gì đẹp ở người anh hùng vừa thể hiện trong bài?\n- GV gợi ý dùng sản phẩm làm báo tường hoặc trưng bày ở góc truyền thống của lớp.\n- GV nhận xét tiết học, nhắc thu dọn giấy vụn, rửa tay; dặn tiết sau mang ảnh gia đình và màu vẽ cho chủ đề mới.","hs":"- HS nêu cảm nghĩ về người anh hùng mình thể hiện.\n- HS nhận nhiệm vụ trưng bày ở góc truyền thống của lớp.\n- HS dọn chỗ ngồi và ghi nhớ đồ dùng tiết sau."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 2, Tiết 3 - Thực hành, sáng tạo"},
{"lop":5,"mon":"Mĩ thuật","tuan":8,"tiet":8,"bai":"Chủ đề 2: Hình tượng anh hùng dân tộc trong mĩ thuật tạo hình Việt Nam (Tiết 4 - Trưng bày, thảo luận và vận dụng)","yccd":"1. Năng lực mĩ thuật\n- Trưng bày, giới thiệu và nêu được cảm nhận về sản phẩm của mình và của bạn.\n- Phân tích được vẻ đẹp, ý nghĩa của sản phẩm theo yếu tố, nguyên lí tạo hình.\n- Biết vận dụng kết quả học tập vào trang trí, làm đẹp cuộc sống.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu quý, tự hào về truyền thống anh hùng và lịch sử dân tộc.\n- Chăm chỉ, có trách nhiệm khi hoàn thành nhiệm vụ học tập.\n4. Tích hợp\n- Năng lực số 2.2 CB2a: Nhận biết được các công nghệ số đơn giản, phù hợp để chia sẻ dữ liệu, thông tin và nội dung số: HS lập được danh mục nguồn tư liệu cho trang trưng bày.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề hình tượng anh hùng dân tộc trong mĩ thuật tạo hình Việt Nam.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (trưng bày, thảo luận và vận dụng).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Chuẩn bị trưng bày","gv":"- GV hướng dẫn HS hoàn thiện, sắp xếp sản phẩm để trưng bày (theo cá nhân/nhóm).\n- GV gợi ý cách giới thiệu, nêu ý tưởng và cảm nhận về sản phẩm.","hs":"- HS hoàn thiện, sắp xếp sản phẩm.\n- HS chuẩn bị lời giới thiệu về sản phẩm của mình."},{"ten":"3. Luyện tập - Trưng bày, thảo luận","gv":"- GV tổ chức cho HS trưng bày, giới thiệu sản phẩm; gợi mở để HS phân tích, thảo luận về vẻ đẹp, ý nghĩa của sản phẩm.\n- GV nhận xét, đánh giá, ghi nhận sự tiến bộ và sáng tạo của HS.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS thảo luận, nhận xét sản phẩm của mình và của bạn."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV gợi ý HS vận dụng sản phẩm, kiến thức của chủ đề hình tượng anh hùng dân tộc trong mĩ thuật tạo hình Việt Nam vào trang trí, làm đẹp góc học tập, lớp học hoặc cuộc sống.\n- GV hệ thống nội dung chủ đề, nhận xét tiết học, tuyên dương; dặn HS chuẩn bị cho chủ đề sau.","hs":"- HS nêu cách vận dụng sản phẩm vào cuộc sống.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 2) HS giới thiệu tác phẩm của mình trước lớp: nhân vật là ai, vì sao em chọn tư thế đó, chi tiết nào em lấy từ tư liệu và chi tiết nào là ý tưởng riêng.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Lớp lập trang trưng bày có ảnh tác phẩm, tên tác giả và danh mục nguồn tư liệu đã sử dụng đặt ở cuối trang.\n⚠ (Miền 4: An toàn) Nói về nhân vật lịch sử phải trung thực với tư liệu, không thêm chi tiết không có thật; ghi đủ nguồn cho ảnh tư liệu; trang trưng bày chỉ chia sẻ trong phạm vi nhà trường.","hs":"- HS trình bày được tác phẩm và phân biệt rõ phần dựa vào tư liệu với phần sáng tạo riêng.\n- HS lập được danh mục nguồn tư liệu cho trang trưng bày."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 2, Tiết 4 - Trưng bày, thảo luận và vận dụng"},
{"lop":5,"mon":"Mĩ thuật","tuan":9,"tiet":9,"bai":"Chủ đề 3: Gia đình (Tiết 1 - Quan sát, nhận biết)","yccd":"1. Năng lực mĩ thuật\n- Quan sát, nhận biết được vẻ đẹp tạo hình, hình ảnh, chất liệu liên quan đến chủ đề.\n- Nêu được cảm nhận ban đầu về đối tượng thẩm mĩ của chủ đề.\n- Có ý thức khai thác hình ảnh, chất liệu để chuẩn bị cho thực hành sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu thương, gắn bó với gia đình; trân trọng tình cảm gia đình.\n- Chăm chỉ, cẩn thận, giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 1.3 CB2a: Xác định được cách tổ chức, lưu trữ và truy xuất dữ liệu, thông tin và nội dung một cách đơn giản trong môi trường số: HS phân tích được cách sắp xếp nhân vật trong tranh đề tài gia đình.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề gia đình.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (quan sát, nhận biết).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Quan sát, nhận biết","gv":"- GV cho HS quan sát hình minh hoạ trong SGK Mĩ thuật 5 và tư liệu GV chuẩn bị thêm về chủ đề gia đình.\n- GV đặt câu hỏi gợi mở để HS nhận ra hình ảnh, chất liệu, cách thể hiện đặc trưng của chủ đề.\n- GV tóm tắt, bổ sung, khắc sâu nội dung Em có biết trong SGK.","hs":"- HS quan sát hình, tư liệu và trả lời câu hỏi.\n- HS nêu hiểu biết, cảm nhận ban đầu về chủ đề.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập - Chia sẻ hiểu biết","gv":"- GV cho HS kể thêm những hình ảnh, tác phẩm cùng chủ đề mà em biết.\n- GV định hướng HS lựa chọn hình ảnh sẽ khai thác cho phần thực hành ở tiết sau.","hs":"- HS chia sẻ trước lớp.\n- HS lựa chọn ý tưởng, hình ảnh cho sản phẩm của mình."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (quan sát, nhận biết).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS xem bộ tranh đề tài gia đình của các hoạ sĩ Việt Nam trên bảo tàng số, phóng to để phân tích cách sắp xếp nhân vật: ai đứng trước, ai đứng sau, khoảng cách giữa các nhân vật nói lên tình cảm gì.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS ghi lại một cách sắp xếp nhân vật mình muốn học hỏi cùng tên bức tranh và tên hoạ sĩ.\n⚠ (Miền 4: An toàn) Tranh của hoạ sĩ thuộc bản quyền của tác giả và nơi lưu giữ; HS chỉ xem để học cách sắp xếp, không sao chép nguyên bố cục rồi nhận là của mình; khi tham khảo phải ghi tên tranh và tác giả.","hs":"- HS phân tích được cách sắp xếp nhân vật trong tranh đề tài gia đình.\n- HS ghi đúng tên tranh, tên hoạ sĩ khi tham khảo."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 3, Tiết 1 - Quan sát, nhận biết"},
{"lop":5,"mon":"Mĩ thuật","tuan":10,"tiet":10,"bai":"Chủ đề 3: Gia đình (Tiết 2 - Cách thực hiện sản phẩm)","yccd":"1. Năng lực mĩ thuật\n- Nêu được các bước cơ bản để thể hiện chủ đề thành sản phẩm mĩ thuật.\n- Lựa chọn được hình ảnh, chất liệu, cách thể hiện phù hợp với khả năng.\n- Biết vận dụng yếu tố và nguyên lí tạo hình đã học vào sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu thương, gắn bó với gia đình; trân trọng tình cảm gia đình.\n- Chăm chỉ, cẩn thận, giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 5.2 CB2b: Nhận ra được các công cụ số đơn giản và các giải pháp công nghệ có thể có để giải quyết những nhu cầu đó: HS thử được nhiều bố cục nhân vật bằng cách kéo thả hình khối trên máy.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề gia đình.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (tìm hiểu cách thực hiện).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Cách thực hiện","gv":"- GV hướng dẫn HS phân tích các bước thực hiện sản phẩm trong SGK Mĩ thuật 5 (khai thác nội dung chủ đề gia đình).\n- GV làm mẫu hoặc mời HS lên thao tác thử một số bước; lưu ý cách chọn hình ảnh, chất liệu phù hợp.","hs":"- HS quan sát, phân tích các bước thực hiện.\n- HS nêu lại các bước và ghi nhớ."},{"ten":"3. Luyện tập - Thử phác ý tưởng","gv":"- GV cho HS phác nhanh ý tưởng, bố cục cho sản phẩm của mình.\n- GV quan sát, gợi ý điều chỉnh để HS chuẩn bị tốt cho tiết thực hành.","hs":"- HS phác ý tưởng, lựa chọn cách thể hiện.\n- HS chuẩn bị chất liệu phù hợp."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (tìm hiểu cách thực hiện).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS dùng ứng dụng vẽ hoặc phần mềm trình chiếu tạo các hình khối đơn giản đại diện cho từng nhân vật rồi kéo thả thử nhiều cách sắp xếp; nhìn ngay được bố cục nào cân đối, bố cục nào chen chúc mà không phải tẩy xoá trên giấy.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) HS chốt một bố cục, ghi lại lí do và chuyển sang phác hình nhân vật trên giấy.\n⚠ (Miền 4: An toàn) HS lưu tệp vào thư mục của mình và đặt tên tệp có tên mình để không nhầm với bài của bạn; không đưa ảnh chụp gia đình mình lên máy dùng chung của lớp.","hs":"- HS thử được nhiều bố cục nhân vật bằng cách kéo thả hình khối trên máy.\n- HS chọn và giải thích được bố cục cuối cùng của mình."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 3, Tiết 2 - Cách thực hiện sản phẩm"},
{"lop":5,"mon":"Mĩ thuật","tuan":11,"tiet":11,"bai":"Chủ đề 3: Gia đình (Tiết 3 - Thực hành, sáng tạo)","yccd":"1. Năng lực mĩ thuật\n- Tạo được sản phẩm mĩ thuật thể hiện nội dung chủ đề theo ý thích.\n- Vận dụng được hình, mảng, màu sắc, đậm nhạt, không gian để làm rõ nội dung.\n- Bước đầu thể hiện được sự sáng tạo và dấu ấn cá nhân trong sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu thương, gắn bó với gia đình; trân trọng tình cảm gia đình.\n- Chăm chỉ, cẩn thận, giữ vệ sinh khi thực hành.","dodung":"- GV: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; 2-3 sản phẩm mẫu ở các mức độ khác nhau; bảng tiêu chí nhận xét sản phẩm viết sẵn; sao giấy màu cho HS bình chọn; nam châm, băng dính giấy để trưng bày; máy tính, máy chiếu và học liệu số.\n- HS: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; bút chì, tẩy, màu vẽ, giấy vẽ A4, giấy màu, kéo, keo dán, đất nặn.\n- Vật liệu thay thế khi lớp thiếu đồ dùng: giấy báo cũ, bìa carton, vỏ hộp sữa, lá cây khô, hột hạt, dây len, vải vụn, cúc áo, ống hút đã rửa sạch; đất nặn có thể thay bằng bột mì trộn muối và màu thực phẩm.\n- An toàn: dùng kéo đầu tròn, chuyền kéo quay mũi về phía mình; dao rọc giấy chỉ dùng khi có GV bên cạnh; keo, màu không đưa lên miệng; hết giờ thu gom giấy vụn, lau bàn, rửa tay.","hoatdong":[{"ten":"1. Khởi động","gv":"- (3 phút) GV cho lớp hát bài Cả nhà thương nhau và hỏi: \"Gia đình em có mấy người, em hay ở cùng ai nhất?\".\n- GV hỏi thêm: \"Cả nhà em thường làm gì cùng nhau vào buổi tối?\" (dự kiến: ăn cơm, học bài, xem tivi, tưới cây).\n- GV dẫn vào bài: tiết này các em hoàn thành sản phẩm về gia đình mình.","hs":"- HS hát và vỗ tay theo nhịp bài hát.\n- HS kể ngắn về các thành viên trong gia đình.\n- HS nêu hoạt động sẽ đưa vào sản phẩm của mình."},{"ten":"2. Khám phá - Nhắc lại yêu cầu","gv":"- (7 phút) GV cho HS xem 3 sản phẩm mẫu và hỏi: \"Bức nào cho em cảm giác ấm áp hơn, vì sao?\".\n- Dự kiến HS đáp: bức có các nhân vật đứng gần nhau, nắm tay, dùng nhiều màu vàng, cam, đỏ nhạt.\n- GV chốt: nhóm người là hình chính đặt giữa tranh, người lớn cao hơn trẻ em; thêm bàn ăn, ngôi nhà, cây làm hình phụ; chọn màu ấm cho không khí gia đình.\n- GV treo bảng tiêu chí nhận xét để HS biết trước đích cần đạt.","hs":"- HS quan sát, so sánh và nêu cảm nhận về sản phẩm mẫu.\n- HS chỉ ra hình chính, hình phụ và màu chủ đạo.\n- HS nhắc lại lưu ý về tỉ lệ người lớn - trẻ em.\n- HS đọc thầm bảng tiêu chí nhận xét."},{"ten":"3. Luyện tập - Thực hành, sáng tạo","gv":"- (17 phút) GV giao việc: mỗi HS hoàn thành tranh vẽ hoặc sản phẩm cắt dán về gia đình; nhóm 2-4 HS có thể làm chung một bức lớn.\n- GV ghi các bước: 1) phác bố cục, xác định nhóm nhân vật chính; 2) vẽ dáng từng người, chú ý tỉ lệ cao thấp; 3) thêm cảnh vật quen thuộc; 4) tô màu quần áo, da, tóc; 5) tô nền và tạo đậm nhạt; 6) hoàn thiện, kí tên.\n- GV làm mẫu chậm bước 2: dùng nét trục so tỉ lệ, người lớn khoảng sáu đầu, trẻ em khoảng năm đầu.\n- GV gợi ý HS thiếu màu dùng giấy báo, vải vụn, dây len làm tóc và quần áo; nhắc dùng kéo an toàn.","hs":"- HS phác bố cục, chọn hoạt động của gia đình để thể hiện.\n- HS vẽ các nhân vật theo tỉ lệ cao thấp hợp lí.\n- HS chọn màu ấm cho nhân vật, tạo đậm nhạt ở nền.\n- HS trao đổi trong nhóm và giữ an toàn khi cắt dán."},{"ten":"4. Trưng bày, nhận xét sản phẩm","gv":"- (6 phút) GV cho HS dán bài lên bảng nhóm, tạo phòng tranh mini Gia đình em ở góc lớp.\n- GV nêu tiêu chí: 1) thấy rõ các thành viên gia đình; 2) bố cục cân đối, tỉ lệ hợp lí; 3) màu hài hoà, có đậm nhạt; 4) bài sạch, có chi tiết riêng của em.\n- GV cho HS tự đánh giá, đi xem, dán sao vào bài mình thích và nói \"Mình thích bài này vì...\"; GV nhận xét 2-3 bài theo tiêu chí.","hs":"- HS trưng bày và giới thiệu người thân có trong tranh.\n- HS tự đối chiếu bài mình với 4 tiêu chí.\n- HS dán sao và nói lời nhận xét về bài của bạn."},{"ten":"5. Vận dụng - Củng cố, dặn dò","gv":"- (2 phút) GV hỏi: em muốn tặng sản phẩm này cho ai trong nhà?\n- GV gợi ý mang tranh về treo ở góc học tập hoặc tặng ông bà, bố mẹ nhân ngày kỉ niệm.\n- GV nhận xét tiết học, nhắc thu giấy vụn, lau bàn, rửa tay; dặn tiết sau mang SGK, màu vẽ cho chủ đề mới.","hs":"- HS nói về người mình muốn tặng sản phẩm.\n- HS nêu cách giữ gìn sản phẩm khi mang về nhà.\n- HS dọn chỗ ngồi và ghi nhớ đồ dùng tiết sau."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 3, Tiết 3 - Thực hành, sáng tạo"},
{"lop":5,"mon":"Mĩ thuật","tuan":12,"tiet":12,"bai":"Chủ đề 3: Gia đình (Tiết 4 - Trưng bày, thảo luận và vận dụng)","yccd":"1. Năng lực mĩ thuật\n- Trưng bày, giới thiệu và nêu được cảm nhận về sản phẩm của mình và của bạn.\n- Phân tích được vẻ đẹp, ý nghĩa của sản phẩm theo yếu tố, nguyên lí tạo hình.\n- Biết vận dụng kết quả học tập vào trang trí, làm đẹp cuộc sống.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu thương, gắn bó với gia đình; trân trọng tình cảm gia đình.\n- Chăm chỉ, cẩn thận, giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 2.5 CB2a: Phân biệt được các chuẩn mực hành vi đơn giản và biết cách sử dụng công nghệ số và tương tác trong môi trường số: HS chia sẻ và lắng nghe về đề tài gia đình một cách tế nhị.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề gia đình.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (trưng bày, thảo luận và vận dụng).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Chuẩn bị trưng bày","gv":"- GV hướng dẫn HS hoàn thiện, sắp xếp sản phẩm để trưng bày (theo cá nhân/nhóm).\n- GV gợi ý cách giới thiệu, nêu ý tưởng và cảm nhận về sản phẩm.","hs":"- HS hoàn thiện, sắp xếp sản phẩm.\n- HS chuẩn bị lời giới thiệu về sản phẩm của mình."},{"ten":"3. Luyện tập - Trưng bày, thảo luận","gv":"- GV tổ chức cho HS trưng bày, giới thiệu sản phẩm; gợi mở để HS phân tích, thảo luận về vẻ đẹp, ý nghĩa của sản phẩm.\n- GV nhận xét, đánh giá, ghi nhận sự tiến bộ và sáng tạo của HS.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS thảo luận, nhận xét sản phẩm của mình và của bạn."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV gợi ý HS vận dụng sản phẩm, kiến thức của chủ đề gia đình vào trang trí, làm đẹp góc học tập, lớp học hoặc cuộc sống.\n- GV hệ thống nội dung chủ đề, nhận xét tiết học, tuyên dương; dặn HS chuẩn bị cho chủ đề sau.","hs":"- HS nêu cách vận dụng sản phẩm vào cuộc sống.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 2) HS giới thiệu tác phẩm về gia đình ở mức mình muốn chia sẻ và lắng nghe bạn; GV hướng dẫn cách nhận xét tế nhị vì mỗi gia đình một hoàn cảnh.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Lớp lập trang trưng bày chỉ gồm ảnh tác phẩm và tên tác giả, không kèm thông tin riêng về gia đình.\n⚠ (Miền 4: An toàn) Không hỏi tò mò về hoàn cảnh gia đình bạn, không kể lại chuyện riêng của bạn cho người khác; trang trưng bày không ghi địa chỉ, nghề nghiệp, số điện thoại của người thân và chỉ chiếu trong lớp.","hs":"- HS chia sẻ và lắng nghe về đề tài gia đình một cách tế nhị.\n- HS nhận ra thông tin nào không nên đưa lên sản phẩm được chia sẻ."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 3, Tiết 4 - Trưng bày, thảo luận và vận dụng"},
{"lop":5,"mon":"Mĩ thuật","tuan":13,"tiet":13,"bai":"Chủ đề 4: Những hoạt động yêu thích ở trường em (Tiết 1 - Quan sát, nhận biết)","yccd":"1. Năng lực mĩ thuật\n- Quan sát, nhận biết được vẻ đẹp tạo hình, hình ảnh, chất liệu liên quan đến chủ đề.\n- Nêu được cảm nhận ban đầu về đối tượng thẩm mĩ của chủ đề.\n- Có ý thức khai thác hình ảnh, chất liệu để chuẩn bị cho thực hành sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu trường lớp, thầy cô, bạn bè; tích cực tham gia hoạt động chung.\n- Chăm chỉ, đoàn kết, giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 1.1 CB2c: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS phân tích được dáng người trong hoạt động nhờ dừng hình clip.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề những hoạt động yêu thích ở trường em.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (quan sát, nhận biết).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Quan sát, nhận biết","gv":"- GV cho HS quan sát hình minh hoạ trong SGK Mĩ thuật 5 và tư liệu GV chuẩn bị thêm về chủ đề những hoạt động yêu thích ở trường em.\n- GV đặt câu hỏi gợi mở để HS nhận ra hình ảnh, chất liệu, cách thể hiện đặc trưng của chủ đề.\n- GV tóm tắt, bổ sung, khắc sâu nội dung Em có biết trong SGK.","hs":"- HS quan sát hình, tư liệu và trả lời câu hỏi.\n- HS nêu hiểu biết, cảm nhận ban đầu về chủ đề.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập - Chia sẻ hiểu biết","gv":"- GV cho HS kể thêm những hình ảnh, tác phẩm cùng chủ đề mà em biết.\n- GV định hướng HS lựa chọn hình ảnh sẽ khai thác cho phần thực hành ở tiết sau.","hs":"- HS chia sẻ trước lớp.\n- HS lựa chọn ý tưởng, hình ảnh cho sản phẩm của mình."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (quan sát, nhận biết).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS xem lại kho ảnh và clip các hoạt động của trường trong năm như hội khoẻ, văn nghệ, lao động, câu lạc bộ; dừng hình ở những khoảnh khắc động để phân tích dáng người đang chạy, đang nhảy, đang cổ vũ.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS chọn một hoạt động, liệt kê các nhân vật và đồ vật cần có rồi phác sơ đồ bố cục trước khi vẽ.\n⚠ (Miền 4: An toàn) Kho ảnh của trường chỉ dùng trong nhà trường; bạn nào không muốn hình mình được sử dụng thì phải bỏ ảnh đó ra; không cắt ghép ảnh của bạn theo cách gây cười, chế giễu.","hs":"- HS phân tích được dáng người trong hoạt động nhờ dừng hình clip.\n- HS lập được sơ đồ bố cục cho bài vẽ của mình."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 4, Tiết 1 - Quan sát, nhận biết"},
{"lop":5,"mon":"Mĩ thuật","tuan":14,"tiet":14,"bai":"Chủ đề 4: Những hoạt động yêu thích ở trường em (Tiết 2 - Cách thực hiện sản phẩm)","yccd":"1. Năng lực mĩ thuật\n- Nêu được các bước cơ bản để thể hiện chủ đề thành sản phẩm mĩ thuật.\n- Lựa chọn được hình ảnh, chất liệu, cách thể hiện phù hợp với khả năng.\n- Biết vận dụng yếu tố và nguyên lí tạo hình đã học vào sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu trường lớp, thầy cô, bạn bè; tích cực tham gia hoạt động chung.\n- Chăm chỉ, đoàn kết, giữ vệ sinh khi thực hành.","dodung":"- GV: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; 2-3 sản phẩm mẫu ở các mức độ khác nhau; bảng tiêu chí nhận xét sản phẩm viết sẵn; sao giấy màu cho HS bình chọn; nam châm, băng dính giấy để trưng bày; máy tính, máy chiếu và học liệu số.\n- HS: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; bút chì, tẩy, màu vẽ, giấy vẽ A4, giấy màu, kéo, keo dán, đất nặn.\n- Vật liệu thay thế khi lớp thiếu đồ dùng: giấy báo cũ, bìa carton, vỏ hộp sữa, lá cây khô, hột hạt, dây len, vải vụn, cúc áo, ống hút đã rửa sạch; đất nặn có thể thay bằng bột mì trộn muối và màu thực phẩm.\n- An toàn: dùng kéo đầu tròn, chuyền kéo quay mũi về phía mình; dao rọc giấy chỉ dùng khi có GV bên cạnh; keo, màu không đưa lên miệng; hết giờ thu gom giấy vụn, lau bàn, rửa tay.","hoatdong":[{"ten":"1. Khởi động","gv":"- (3 phút) GV tổ chức trò chơi Kể nhanh hoạt động ở trường: mỗi tổ nói một hoạt động không trùng nhau trong 30 giây.\n- GV hỏi: \"Hoạt động nào em thích nhất, lúc đó em đang làm gì?\" (dự kiến: đá cầu, nhảy dây, múa hát sân trường, đọc sách thư viện).\n- GV dẫn vào bài: tiết này lớp tìm hiểu cách thực hiện sản phẩm cho chủ đề.","hs":"- HS thi kể nhanh các hoạt động ở trường.\n- HS nêu hoạt động mình thích và động tác lúc đó.\n- HS nhắc lại nhiệm vụ tiết học."},{"ten":"2. Khám phá - Cách thực hiện","gv":"- (10 phút) GV cho HS mở SGK Mĩ thuật 5, quan sát hình các bước và hỏi: \"Bước nào làm trước, vì sao phải phác hình trước khi tô màu?\".\n- Dự kiến HS đáp: phác trước để dễ sửa bố cục, tô màu rồi thì khó chỉnh lại.\n- GV làm mẫu chậm cách phác dáng người đang hoạt động: dùng nét trục đầu - thân - tay - chân để bắt dáng chạy, nhảy, cúi.\n- GV mời 1-2 HS lên bảng thao tác thử một bước, cả lớp quan sát và nhận xét.","hs":"- HS quan sát hình trong SGK, nêu thứ tự các bước.\n- HS giải thích vì sao phải phác hình trước khi tô màu.\n- HS theo dõi GV làm mẫu và tập bắt dáng ra giấy nháp.\n- HS lên bảng thao tác thử, lớp nhận xét."},{"ten":"3. Luyện tập - Thử phác ý tưởng","gv":"- (14 phút) GV cho HS phác nhanh hai phương án bố cục ra giấy nháp trong 8 phút rồi chọn một phương án ưng ý.\n- GV gợi ý: chọn một hoạt động, đặt nhóm nhân vật chính ở giữa, thêm sân trường, cây, cột cờ làm hình phụ.\n- GV đi từng bàn hỏi: \"Nhân vật chính của em đang làm động tác gì?\"; HS thiếu giấy có thể phác vào mặt sau tờ lịch hoặc giấy báo.\n- GV nêu các lựa chọn chất liệu: vẽ màu, xé dán giấy màu hoặc ghép bìa carton, lá khô tuỳ đồ dùng có sẵn.","hs":"- HS phác hai phương án bố cục ra nháp rồi chọn một.\n- HS xác định nhân vật chính và động tác sẽ thể hiện.\n- HS nêu chất liệu sẽ dùng cho sản phẩm.\n- HS ghi lại vật liệu cần chuẩn bị thêm cho tiết sau."},{"ten":"4. Chia sẻ, góp ý phác thảo","gv":"- (5 phút) GV cho HS đổi nháp theo cặp, góp ý theo 3 câu hỏi: hình chính đã rõ chưa? bố cục có bị lệch không? còn chỗ nào trống quá không?\n- GV chọn 2 phác thảo dán lên bảng, cùng lớp phân tích điểm được và chỗ cần chỉnh.\n- GV chốt tiêu chí sẽ dùng ở tiết thực hành: hình chính rõ, bố cục cân đối, màu có đậm nhạt, bài sạch và có ý tưởng riêng.","hs":"- HS đổi nháp, góp ý cho bạn theo 3 câu hỏi.\n- HS nêu chỗ cần chỉnh trong phác thảo của mình.\n- HS ghi nhớ 4 tiêu chí đánh giá sản phẩm."},{"ten":"5. Vận dụng - Củng cố, dặn dò","gv":"- (3 phút) GV cùng HS nhắc lại các bước thực hiện sản phẩm theo đúng trình tự.\n- GV giao nhiệm vụ quan sát: giờ ra chơi chú ý dáng người khi chạy, nhảy để bài vẽ sinh động hơn.\n- GV nhận xét tiết học, nhắc cất đồ dùng gọn gàng; dặn tiết sau mang phác thảo, màu vẽ, giấy màu, kéo, keo và vật liệu tái sử dụng.","hs":"- HS nhắc lại các bước thực hiện sản phẩm.\n- HS nhận nhiệm vụ quan sát dáng người khi ra chơi.\n- HS ghi rõ đồ dùng cần mang cho tiết thực hành."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 4, Tiết 2 - Cách thực hiện sản phẩm"},
{"lop":5,"mon":"Mĩ thuật","tuan":15,"tiet":15,"bai":"Chủ đề 4: Những hoạt động yêu thích ở trường em (Tiết 3 - Thực hành, sáng tạo)","yccd":"1. Năng lực mĩ thuật\n- Tạo được sản phẩm mĩ thuật thể hiện nội dung chủ đề theo ý thích.\n- Vận dụng được hình, mảng, màu sắc, đậm nhạt, không gian để làm rõ nội dung.\n- Bước đầu thể hiện được sự sáng tạo và dấu ấn cá nhân trong sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu trường lớp, thầy cô, bạn bè; tích cực tham gia hoạt động chung.\n- Chăm chỉ, đoàn kết, giữ vệ sinh khi thực hành.","dodung":"- GV: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; 2-3 sản phẩm mẫu ở các mức độ khác nhau; bảng tiêu chí nhận xét sản phẩm viết sẵn; sao giấy màu cho HS bình chọn; nam châm, băng dính giấy để trưng bày; máy tính, máy chiếu và học liệu số.\n- HS: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; bút chì, tẩy, màu vẽ, giấy vẽ A4, giấy màu, kéo, keo dán, đất nặn.\n- Vật liệu thay thế khi lớp thiếu đồ dùng: giấy báo cũ, bìa carton, vỏ hộp sữa, lá cây khô, hột hạt, dây len, vải vụn, cúc áo, ống hút đã rửa sạch; đất nặn có thể thay bằng bột mì trộn muối và màu thực phẩm.\n- An toàn: dùng kéo đầu tròn, chuyền kéo quay mũi về phía mình; dao rọc giấy chỉ dùng khi có GV bên cạnh; keo, màu không đưa lên miệng; hết giờ thu gom giấy vụn, lau bàn, rửa tay.","hoatdong":[{"ten":"1. Khởi động","gv":"- (3 phút) GV cho lớp chơi Bắt dáng: GV hô tên hoạt động (đá cầu, nhảy dây, đọc sách), HS làm nhanh dáng đó tại chỗ.\n- GV hỏi: \"Khi đá cầu, tay và chân em ở tư thế nào?\" (dự kiến: một chân co lên, hai tay dang ra giữ thăng bằng).\n- GV dẫn vào bài: tiết này các em hoàn thành sản phẩm về hoạt động yêu thích ở trường.","hs":"- HS làm dáng theo hiệu lệnh của GV.\n- HS mô tả tư thế tay, chân của dáng vừa làm.\n- HS lấy phác thảo tiết trước và đồ dùng ra bàn."},{"ten":"2. Khám phá - Nhắc lại yêu cầu","gv":"- (6 phút) GV cho HS xem lại 2 sản phẩm mẫu và hỏi: \"Nhìn vào đâu em biết các bạn trong tranh đang chơi trò gì?\".\n- Dự kiến HS đáp: nhìn động tác tay chân và đồ vật trên tay như quả cầu, dây nhảy, quả bóng.\n- GV chốt 4 lưu ý: nhóm nhân vật chính vẽ to ở giữa; động tác rõ ràng; thêm cột cờ, cây, lớp học làm nền; màu áo tươi nổi trên nền dịu.\n- GV treo bảng tiêu chí nhận xét để HS biết trước đích cần đạt.","hs":"- HS quan sát sản phẩm mẫu và trả lời câu hỏi.\n- HS chỉ ra chi tiết giúp nhận biết trò chơi trong tranh.\n- HS nhắc lại 4 lưu ý trước khi thực hành.\n- HS đọc thầm bảng tiêu chí nhận xét."},{"ten":"3. Luyện tập - Thực hành, sáng tạo","gv":"- (18 phút) GV giao việc: HS hoàn thành sản phẩm từ phác thảo tiết trước, làm cá nhân hoặc nhóm 2-4 HS ghép tranh chung.\n- GV ghi các bước: 1) can lại bố cục đã chọn; 2) vẽ dáng nhân vật chính; 3) thêm hình phụ và cảnh trường; 4) tô màu nhân vật; 5) tô nền, tạo đậm nhạt cho có xa - gần; 6) hoàn thiện, kí tên.\n- GV làm mẫu chậm bước 5: nền phía xa tô nhạt hơn, phía gần tô đậm và rõ chi tiết hơn.\n- GV hỗ trợ HS làm chậm bằng cách giảm số nhân vật; HS thiếu màu dùng giấy báo, vải vụn, lá khô; nhắc an toàn khi dùng kéo, keo.","hs":"- HS làm bài theo 6 bước, bám sát phác thảo tiết trước.\n- HS vẽ rõ động tác của nhân vật chính đang tham gia hoạt động.\n- HS tô nền phía xa nhạt, phía gần đậm để tạo không gian.\n- HS trao đổi trong nhóm, giữ trật tự và dùng kéo, keo an toàn."},{"ten":"4. Trưng bày, nhận xét sản phẩm","gv":"- (5 phút) GV cho HS gắn bài lên bảng nhóm theo từng hoạt động, tạo phòng tranh mini Trường em ở góc lớp.\n- GV nêu tiêu chí: 1) nhận ra hoạt động đang diễn ra; 2) bố cục cân đối, hình chính rõ; 3) màu hài hoà, có đậm nhạt; 4) bài sạch, có ý tưởng riêng.\n- GV cho HS tự đánh giá rồi đi xem, dán sao vào bài mình thích và nói \"Mình thích bài này vì...\"; GV nhận xét 2-3 bài theo tiêu chí.","hs":"- HS trưng bày bài theo nhóm hoạt động.\n- HS tự đối chiếu bài mình với 4 tiêu chí.\n- HS dán sao, nhận xét bài bạn và giới thiệu bài của mình."},{"ten":"5. Vận dụng - Củng cố, dặn dò","gv":"- (3 phút) GV hỏi: hoạt động nào ở trường làm em vui nhất và vì sao?\n- GV gợi ý dùng các bài của lớp làm báo tường hoặc trang trí bảng tin của trường.\n- GV nhận xét tiết học, nhắc thu giấy vụn, lau bàn, rửa tay; dặn tiết sau ôn lại các chủ đề đã học để chuẩn bị đánh giá cuối học kì I.","hs":"- HS nói về hoạt động mình yêu thích ở trường.\n- HS nhận nhiệm vụ làm báo tường của lớp.\n- HS dọn chỗ ngồi và ghi nhớ việc chuẩn bị tiết sau."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 4, Tiết 3 - Thực hành, sáng tạo"},
{"lop":5,"mon":"Mĩ thuật","tuan":16,"tiet":16,"bai":"Chủ đề 4: Những hoạt động yêu thích ở trường em (Tiết 4 - Trưng bày, thảo luận và vận dụng)","yccd":"1. Năng lực mĩ thuật\n- Trưng bày, giới thiệu và nêu được cảm nhận về sản phẩm của mình và của bạn.\n- Phân tích được vẻ đẹp, ý nghĩa của sản phẩm theo yếu tố, nguyên lí tạo hình.\n- Biết vận dụng kết quả học tập vào trang trí, làm đẹp cuộc sống.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu trường lớp, thầy cô, bạn bè; tích cực tham gia hoạt động chung.\n- Chăm chỉ, đoàn kết, giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 3.1 CB2a: Xác định được các cách tạo và chỉnh sửa nội dung đơn giản ở các định dạng đơn giản: HS viết được chú thích nêu rõ phần sáng tạo thêm so với ảnh tư liệu.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề những hoạt động yêu thích ở trường em.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (trưng bày, thảo luận và vận dụng).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Chuẩn bị trưng bày","gv":"- GV hướng dẫn HS hoàn thiện, sắp xếp sản phẩm để trưng bày (theo cá nhân/nhóm).\n- GV gợi ý cách giới thiệu, nêu ý tưởng và cảm nhận về sản phẩm.","hs":"- HS hoàn thiện, sắp xếp sản phẩm.\n- HS chuẩn bị lời giới thiệu về sản phẩm của mình."},{"ten":"3. Luyện tập - Trưng bày, thảo luận","gv":"- GV tổ chức cho HS trưng bày, giới thiệu sản phẩm; gợi mở để HS phân tích, thảo luận về vẻ đẹp, ý nghĩa của sản phẩm.\n- GV nhận xét, đánh giá, ghi nhận sự tiến bộ và sáng tạo của HS.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS thảo luận, nhận xét sản phẩm của mình và của bạn."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV gợi ý HS vận dụng sản phẩm, kiến thức của chủ đề những hoạt động yêu thích ở trường em vào trang trí, làm đẹp góc học tập, lớp học hoặc cuộc sống.\n- GV hệ thống nội dung chủ đề, nhận xét tiết học, tuyên dương; dặn HS chuẩn bị cho chủ đề sau.","hs":"- HS nêu cách vận dụng sản phẩm vào cuộc sống.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Lớp làm trang trưng bày Những hoạt động yêu thích ở trường em gồm tranh của HS đặt cạnh ảnh tư liệu tương ứng; HS viết chú thích cho biết mình đã thêm bớt gì so với ảnh.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 2) HS bình chọn tác phẩm diễn tả được không khí sôi nổi nhất và nêu căn cứ bình chọn, tránh bình chọn theo cảm tình bạn bè.\n⚠ (Miền 4: An toàn) Ảnh tư liệu có mặt bạn chỉ được dùng khi bạn đồng ý; trang trưng bày chia sẻ trong trường, muốn đăng lên trang thông tin của trường phải được nhà trường cho phép.","hs":"- HS viết được chú thích nêu rõ phần sáng tạo thêm so với ảnh tư liệu.\n- HS bình chọn dựa trên tiêu chí chứ không theo cảm tình."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 4, Tiết 4 - Trưng bày, thảo luận và vận dụng"},
{"lop":5,"mon":"Mĩ thuật","tuan":17,"tiet":17,"bai":"Đánh giá cuối học kì I","yccd":"1. Năng lực mĩ thuật\n- Vận dụng kiến thức, kĩ năng đã học trong học kì để hoàn thành một sản phẩm mĩ thuật theo yêu cầu.\n- Thể hiện được yếu tố, nguyên lí tạo hình (hình, mảng, màu sắc, đậm nhạt, không gian) phù hợp nội dung.\n- Giới thiệu và nêu được cảm nhận về sản phẩm của mình.\n2. Năng lực chung\n- Tự chủ và tự học; giải quyết vấn đề và sáng tạo khi hoàn thành sản phẩm.\n3. Phẩm chất\n- Chăm chỉ, trung thực, có trách nhiệm; tự tin thể hiện sản phẩm của mình.","dodung":"- GV: đề bài thực hành và bảng tiêu chí đánh giá viết sẵn trên giấy khổ lớn; một vài sản phẩm mẫu để HS hình dung mức cần đạt; giấy vẽ, màu dự phòng cho HS quên đồ dùng; phiếu tự đánh giá; sao giấy màu, nam châm, băng dính giấy để trưng bày; thiết bị trình chiếu học liệu số.\n- HS: đồ dùng học tập môn Mĩ thuật; giấy vẽ, bút chì, tẩy, màu vẽ, giấy màu, kéo, keo dán và chất liệu đã chuẩn bị.\n- Vật liệu thay thế khi thiếu đồ dùng: giấy báo cũ, bìa carton, vỏ hộp, lá cây khô, hột hạt, dây len, vải vụn để cắt dán hoặc tạo hình nổi.\n- An toàn: dùng kéo đầu tròn, không đùa nghịch khi cầm kéo; keo, màu không đưa lên miệng; làm xong thu gom giấy vụn, lau bàn ghế và rửa tay sạch.","hoatdong":[{"ten":"1. Khởi động - Nêu yêu cầu và tiêu chí","gv":"- (4 phút) GV ổn định lớp, nêu mục đích tiết đánh giá cuối học kì I: mỗi HS hoàn thành một sản phẩm mĩ thuật theo chủ đề đã học.\n- GV ghi đề lên bảng, cho HS chọn một trong các chủ đề đã học: yếu tố tạo hình, anh hùng dân tộc, gia đình, hoạt động ở trường.\n- GV treo bảng tiêu chí và giải thích từng ý: 1) đúng chủ đề, có hình ảnh chính rõ; 2) bố cục cân đối, có hình phụ và nền; 3) màu sắc hài hoà, có đậm nhạt; 4) hoàn thiện sạch sẽ, có ý tưởng riêng.\n- GV nhắc HS chọn chất liệu vừa sức: vẽ màu, xé dán giấy hoặc ghép vật liệu tái sử dụng như bìa carton, giấy báo, lá khô, vải vụn.","hs":"- HS lắng nghe, nắm mục đích và yêu cầu của tiết đánh giá.\n- HS chọn một chủ đề đã học trong học kì để thể hiện.\n- HS đọc lại 4 tiêu chí, hỏi lại GV chỗ mình chưa rõ.\n- HS chuẩn bị giấy, màu và chất liệu phù hợp với khả năng của mình."},{"ten":"2. Thực hành - Hoàn thành sản phẩm","gv":"- (20 phút) GV cho HS làm bài độc lập, gợi ý chia thời gian: 5 phút phác bố cục, 10 phút vẽ hình và tô màu, 5 phút hoàn thiện.\n- GV ghi các bước lên bảng: 1) phác bố cục bằng nét chì mờ; 2) vẽ hình ảnh chính; 3) thêm hình phụ và nền; 4) tô màu mảng lớn trước, mảng nhỏ sau; 5) tạo đậm nhạt; 6) tẩy nét thừa, kí tên.\n- GV bao quát lớp, báo thời gian ở phút thứ 10 và phút thứ 17; hỗ trợ HS quên đồ dùng bằng giấy và màu dự phòng.\n- GV nhắc an toàn: dùng kéo cẩn thận, không đùa nghịch khi cầm kéo; keo và màu không đưa lên miệng.","hs":"- HS làm bài độc lập theo các bước và thời gian gợi ý.\n- HS thể hiện rõ hình ảnh chính đúng chủ đề đã chọn.\n- HS tạo đậm nhạt để bài có trọng tâm.\n- HS giữ trật tự, dùng kéo và keo an toàn."},{"ten":"3. Trưng bày, tự đánh giá và đánh giá chéo","gv":"- (8 phút) GV cho HS dán bài lên bảng nhóm theo chủ đề, tạo phòng tranh mini ở góc lớp.\n- GV phát phiếu tự đánh giá, hướng dẫn HS đối chiếu bài mình với 4 tiêu chí và đánh dấu mức Đạt hoặc Cần cố gắng.\n- GV cho HS đi xem bài bạn, dán một sao giấy vào bài mình thích và nói theo mẫu \"Mình thích bài này vì...\".\n- GV mời 3-4 HS giới thiệu sản phẩm: chủ đề, hình ảnh chính, chất liệu và điều em thích nhất ở bài mình.","hs":"- HS trưng bày bài ngay ngắn theo nhóm chủ đề.\n- HS tự đánh giá bài mình theo 4 tiêu chí.\n- HS dán sao và nói lời nhận xét theo mẫu câu.\n- HS giới thiệu sản phẩm của mình trước lớp."},{"ten":"4. Vận dụng - Tổng kết, dặn dò","gv":"- (3 phút) GV nhận xét chung kết quả học kì I theo tiêu chí, ghi nhận sự tiến bộ của từng HS.\n- GV gợi ý vận dụng: giữ lại sản phẩm làm bộ sưu tập cá nhân, dùng trang trí góc học tập hoặc tặng người thân.\n- GV tuyên dương HS có ý tưởng riêng và nhóm giữ vệ sinh tốt; nhắc thu giấy vụn, lau bàn, rửa tay.\n- GV dặn nội dung học kì II và đồ dùng cần chuẩn bị cho chủ đề tiếp theo.","hs":"- HS lắng nghe nhận xét, nhận ra điều mình làm tốt.\n- HS nêu cách giữ gìn và sử dụng sản phẩm.\n- HS thu dọn lớp học, rửa tay sạch sẽ.\n- HS ghi nhớ đồ dùng cần chuẩn bị cho học kì II."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Đánh giá cuối học kì I"},
{"lop":5,"mon":"Mĩ thuật","tuan":18,"tiet":18,"bai":"Chủ đề 5: Những việc làm bình dị mà cao quý trong cuộc sống (Tiết 1 - Quan sát, nhận biết)","yccd":"1. Năng lực mĩ thuật\n- Quan sát, nhận biết được vẻ đẹp tạo hình, hình ảnh, chất liệu liên quan đến chủ đề.\n- Nêu được cảm nhận ban đầu về đối tượng thẩm mĩ của chủ đề.\n- Có ý thức khai thác hình ảnh, chất liệu để chuẩn bị cho thực hành sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Trân trọng những việc làm tốt đẹp, tử tế trong cuộc sống; có ý thức làm việc tốt.\n- Chăm chỉ, nhân ái, có trách nhiệm.\n4. Tích hợp\n- Năng lực số 1.2 CB2a: Phát hiện được độ tin cậy và độ chính xác của các nguồn chung của dữ liệu, thông tin và nội dung số: HS kiểm chứng được câu chuyện qua hai nguồn trước khi chọn làm đề tài.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề những việc làm bình dị mà cao quý trong cuộc sống.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (quan sát, nhận biết).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Quan sát, nhận biết","gv":"- GV cho HS quan sát hình minh hoạ trong SGK Mĩ thuật 5 và tư liệu GV chuẩn bị thêm về chủ đề những việc làm bình dị mà cao quý trong cuộc sống.\n- GV đặt câu hỏi gợi mở để HS nhận ra hình ảnh, chất liệu, cách thể hiện đặc trưng của chủ đề.\n- GV tóm tắt, bổ sung, khắc sâu nội dung Em có biết trong SGK.","hs":"- HS quan sát hình, tư liệu và trả lời câu hỏi.\n- HS nêu hiểu biết, cảm nhận ban đầu về chủ đề.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập - Chia sẻ hiểu biết","gv":"- GV cho HS kể thêm những hình ảnh, tác phẩm cùng chủ đề mà em biết.\n- GV định hướng HS lựa chọn hình ảnh sẽ khai thác cho phần thực hành ở tiết sau.","hs":"- HS chia sẻ trước lớp.\n- HS lựa chọn ý tưởng, hình ảnh cho sản phẩm của mình."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (quan sát, nhận biết).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS tìm trên báo dành cho thiếu nhi và trang của cơ quan nhà nước những câu chuyện về việc làm tử tế của người bình thường, đối chiếu hai nguồn để chắc chắn câu chuyện có thật trước khi lấy làm đề tài.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS ghi vào phiếu câu chuyện, nhân vật, nguồn tin và chi tiết nào có thể chuyển thành hình ảnh trong tranh.\n⚠ (Miền 4: An toàn) Trên mạng có nhiều câu chuyện cảm động được dựng lên hoặc do máy viết ra để câu người xem; HS phải kiểm tra ở nguồn chính thống trước khi tin và trước khi kể lại cho bạn.","hs":"- HS kiểm chứng được câu chuyện qua hai nguồn trước khi chọn làm đề tài.\n- HS ghi được phiếu tư liệu có nguồn rõ ràng."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 5, Tiết 1 - Quan sát, nhận biết"},
{"lop":5,"mon":"Mĩ thuật","tuan":19,"tiet":19,"bai":"Chủ đề 5: Những việc làm bình dị mà cao quý trong cuộc sống (Tiết 2 - Cách thực hiện sản phẩm)","yccd":"1. Năng lực mĩ thuật\n- Nêu được các bước cơ bản để thể hiện chủ đề thành sản phẩm mĩ thuật.\n- Lựa chọn được hình ảnh, chất liệu, cách thể hiện phù hợp với khả năng.\n- Biết vận dụng yếu tố và nguyên lí tạo hình đã học vào sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Trân trọng những việc làm tốt đẹp, tử tế trong cuộc sống; có ý thức làm việc tốt.\n- Chăm chỉ, nhân ái, có trách nhiệm.\n4. Tích hợp\n- Năng lực số 3.2 CB2a: Chọn được các cách sửa đổi, tinh chỉnh, cải thiện và tích hợp các mục đơn giản có nội dung và thông tin mới để tạo ra những nội dung và thông tin mới và độc đáo: HS tự chỉnh sửa được tỉ lệ, tư thế theo tư liệu.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề những việc làm bình dị mà cao quý trong cuộc sống.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (tìm hiểu cách thực hiện).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Cách thực hiện","gv":"- GV hướng dẫn HS phân tích các bước thực hiện sản phẩm trong SGK Mĩ thuật 5 (khai thác nội dung chủ đề những việc làm bình dị mà cao quý trong cuộc sống).\n- GV làm mẫu hoặc mời HS lên thao tác thử một số bước; lưu ý cách chọn hình ảnh, chất liệu phù hợp.","hs":"- HS quan sát, phân tích các bước thực hiện.\n- HS nêu lại các bước và ghi nhớ."},{"ten":"3. Luyện tập - Thử phác ý tưởng","gv":"- GV cho HS phác nhanh ý tưởng, bố cục cho sản phẩm của mình.\n- GV quan sát, gợi ý điều chỉnh để HS chuẩn bị tốt cho tiết thực hành.","hs":"- HS phác ý tưởng, lựa chọn cách thể hiện.\n- HS chuẩn bị chất liệu phù hợp."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (tìm hiểu cách thực hiện).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS xem clip tư liệu về công việc mình chọn, dừng hình để ghi lại dáng đặc trưng của nghề như dáng cúi của người quét đường, dáng với tay của người thợ điện, cùng các đồ vật đi kèm, sau đó phác dáng theo ghi chép.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) HS đối chiếu bản phác với ảnh dừng hình để chỉnh lại tỉ lệ và tư thế cho đúng đặc trưng của nghề.\n⚠ (Miền 4: An toàn) HS mở đúng clip GV cung cấp, không bấm sang clip gợi ý bên cạnh; nếu muốn chụp ảnh người lao động ngoài đời làm tư liệu thì phải xin phép người ấy trước.","hs":"- HS ghi và phác được dáng đặc trưng của nghề nhờ dừng hình clip.\n- HS tự chỉnh sửa được tỉ lệ, tư thế theo tư liệu."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 5, Tiết 2 - Cách thực hiện sản phẩm"},
{"lop":5,"mon":"Mĩ thuật","tuan":20,"tiet":20,"bai":"Chủ đề 5: Những việc làm bình dị mà cao quý trong cuộc sống (Tiết 3 - Thực hành, sáng tạo)","yccd":"1. Năng lực mĩ thuật\n- Tạo được sản phẩm mĩ thuật thể hiện nội dung chủ đề theo ý thích.\n- Vận dụng được hình, mảng, màu sắc, đậm nhạt, không gian để làm rõ nội dung.\n- Bước đầu thể hiện được sự sáng tạo và dấu ấn cá nhân trong sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Trân trọng những việc làm tốt đẹp, tử tế trong cuộc sống; có ý thức làm việc tốt.\n- Chăm chỉ, nhân ái, có trách nhiệm.","dodung":"- GV: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; 2-3 sản phẩm mẫu ở các mức độ khác nhau; bảng tiêu chí nhận xét sản phẩm viết sẵn; sao giấy màu cho HS bình chọn; nam châm, băng dính giấy để trưng bày; máy tính, máy chiếu và học liệu số.\n- HS: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; bút chì, tẩy, màu vẽ, giấy vẽ A4, giấy màu, kéo, keo dán, đất nặn.\n- Vật liệu thay thế khi lớp thiếu đồ dùng: giấy báo cũ, bìa carton, vỏ hộp sữa, lá cây khô, hột hạt, dây len, vải vụn, cúc áo, ống hút đã rửa sạch; đất nặn có thể thay bằng bột mì trộn muối và màu thực phẩm.\n- An toàn: dùng kéo đầu tròn, chuyền kéo quay mũi về phía mình; dao rọc giấy chỉ dùng khi có GV bên cạnh; keo, màu không đưa lên miệng; hết giờ thu gom giấy vụn, lau bàn, rửa tay.","hoatdong":[{"ten":"1. Khởi động","gv":"- (3 phút) GV chiếu 3 bức ảnh: cô lao công quét sân trường, bạn nhỏ dắt cụ già qua đường, chú bộ đội giúp dân; hỏi \"Người trong ảnh đang làm việc gì?\".\n- GV hỏi thêm: \"Việc làm ấy giúp ích gì cho mọi người?\" (dự kiến: giữ sân trường sạch, giúp người khác an toàn, giúp dân bớt vất vả).\n- GV dẫn vào bài: tiết này các em hoàn thành sản phẩm về một việc làm tốt đẹp đã chọn.","hs":"- HS quan sát ảnh và nói việc làm nhận ra.\n- HS nêu ích lợi của những việc làm đó.\n- HS nhắc lại nhiệm vụ, bày phác thảo và đồ dùng."},{"ten":"2. Khám phá - Nhắc lại yêu cầu","gv":"- (6 phút) GV cho HS xem lại sản phẩm mẫu và hỏi: \"Chi tiết nào cho biết nhân vật đang làm việc tốt?\".\n- Dự kiến HS đáp: đồ vật cầm trên tay như chổi, thùng rác, cặp sách; tư thế cúi xuống, đưa tay giúp đỡ; nét mặt tươi vui.\n- GV chốt: nhân vật đang hành động là hình chính, vẽ to ở giữa tranh; thêm đường phố, sân trường làm nền; màu tươi cho nhân vật, màu dịu cho nền.\n- GV treo bảng tiêu chí nhận xét để HS biết trước đích cần đạt.","hs":"- HS quan sát mẫu, chỉ ra chi tiết kể việc làm tốt.\n- HS nêu tư thế nhân vật mình sẽ thể hiện.\n- HS nhắc lại lưu ý về hình chính và màu sắc.\n- HS đọc thầm bảng tiêu chí nhận xét."},{"ten":"3. Luyện tập - Thực hành, sáng tạo","gv":"- (18 phút) GV giao việc: mỗi HS hoàn thành sản phẩm kể lại một việc làm bình dị mà cao quý; nhóm 2-4 HS có thể ghép thành tranh chung.\n- GV ghi các bước: 1) phác bố cục, đặt nhân vật chính; 2) vẽ dáng nhân vật đang hành động; 3) thêm đồ vật và cảnh vật; 4) tô màu nhân vật; 5) tô nền, tạo đậm nhạt; 6) hoàn thiện, kí tên.\n- GV làm mẫu chậm bước 2: bắt dáng cúi người, đưa tay bằng ba nét trục để động tác không bị cứng.\n- GV gợi ý HS thiếu đồ dùng dùng giấy báo, bìa carton, vải vụn, dây len cắt dán nhân vật; nhắc an toàn khi dùng kéo, keo.","hs":"- HS làm bài theo 6 bước, bám sát phác thảo đã chọn.\n- HS bắt dáng nhân vật bằng nét trục cho mềm mại.\n- HS thêm đồ vật để người xem hiểu việc làm trong tranh.\n- HS giữ an toàn khi dùng kéo, keo và giữ chỗ ngồi sạch."},{"ten":"4. Trưng bày, nhận xét sản phẩm","gv":"- (5 phút) GV cho HS dán bài lên bảng nhóm, đặt tên góc trưng bày là Việc tốt quanh em.\n- GV nêu tiêu chí: 1) kể rõ được việc làm tốt; 2) bố cục cân đối, hình chính rõ; 3) màu hài hoà, có đậm nhạt; 4) bài sạch, có ý tưởng riêng.\n- GV cho HS tự đánh giá, đi xem và dán sao vào bài mình thích, nói \"Mình thích bài này vì...\"; GV nhận xét 2-3 bài theo tiêu chí.","hs":"- HS trưng bày bài và ghi tên việc làm ở bên dưới.\n- HS tự đối chiếu bài mình với 4 tiêu chí.\n- HS dán sao, nhận xét bài bạn theo mẫu câu."},{"ten":"5. Vận dụng - Củng cố, dặn dò","gv":"- (3 phút) GV hỏi: tuần này em sẽ làm một việc tốt nào ở lớp hoặc ở nhà?\n- GV gợi ý dùng các sản phẩm làm bảng tin Việc tốt mỗi ngày của lớp.\n- GV nhận xét tiết học, tuyên dương nhóm giữ vệ sinh tốt; nhắc thu giấy vụn, rửa tay; dặn tiết sau mang tranh, ảnh về cảnh đẹp quê hương.","hs":"- HS nêu việc tốt sẽ làm trong tuần.\n- HS nhận nhiệm vụ trang trí bảng tin của lớp.\n- HS dọn chỗ ngồi, rửa tay và ghi nhớ đồ dùng tiết sau."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 5, Tiết 3 - Thực hành, sáng tạo"},
{"lop":5,"mon":"Mĩ thuật","tuan":21,"tiet":21,"bai":"Chủ đề 5: Những việc làm bình dị mà cao quý trong cuộc sống (Tiết 4 - Trưng bày, thảo luận và vận dụng)","yccd":"1. Năng lực mĩ thuật\n- Trưng bày, giới thiệu và nêu được cảm nhận về sản phẩm của mình và của bạn.\n- Phân tích được vẻ đẹp, ý nghĩa của sản phẩm theo yếu tố, nguyên lí tạo hình.\n- Biết vận dụng kết quả học tập vào trang trí, làm đẹp cuộc sống.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Trân trọng những việc làm tốt đẹp, tử tế trong cuộc sống; có ý thức làm việc tốt.\n- Chăm chỉ, nhân ái, có trách nhiệm.\n4. Tích hợp\n- Năng lực số 3.3 CB2a: Xác định được các quy tắc đơn giản về bản quyền và giấy phép áp dụng cho dữ liệu, thông tin và nội dung số: HS ghi đủ nguồn và tên tác giả trên sản phẩm chung của lớp.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề những việc làm bình dị mà cao quý trong cuộc sống.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (trưng bày, thảo luận và vận dụng).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Chuẩn bị trưng bày","gv":"- GV hướng dẫn HS hoàn thiện, sắp xếp sản phẩm để trưng bày (theo cá nhân/nhóm).\n- GV gợi ý cách giới thiệu, nêu ý tưởng và cảm nhận về sản phẩm.","hs":"- HS hoàn thiện, sắp xếp sản phẩm.\n- HS chuẩn bị lời giới thiệu về sản phẩm của mình."},{"ten":"3. Luyện tập - Trưng bày, thảo luận","gv":"- GV tổ chức cho HS trưng bày, giới thiệu sản phẩm; gợi mở để HS phân tích, thảo luận về vẻ đẹp, ý nghĩa của sản phẩm.\n- GV nhận xét, đánh giá, ghi nhận sự tiến bộ và sáng tạo của HS.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS thảo luận, nhận xét sản phẩm của mình và của bạn."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV gợi ý HS vận dụng sản phẩm, kiến thức của chủ đề những việc làm bình dị mà cao quý trong cuộc sống vào trang trí, làm đẹp góc học tập, lớp học hoặc cuộc sống.\n- GV hệ thống nội dung chủ đề, nhận xét tiết học, tuyên dương; dặn HS chuẩn bị cho chủ đề sau.","hs":"- HS nêu cách vận dụng sản phẩm vào cuộc sống.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 2) Lớp lập trang trưng bày kèm mỗi tranh một câu chuyện ngắn về việc làm tử tế và gửi tới các lớp trong trường để lan toả; HS tập viết câu chuyện ngắn gọn, trung thực.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) HS ghi rõ nguồn của câu chuyện và tên tác giả tranh ở cuối mỗi phần.\n⚠ (Miền 4: An toàn) Chỉ kể lại câu chuyện đã kiểm chứng, không thêm chi tiết cho cảm động; nếu câu chuyện về một người cụ thể ở địa phương thì phải hỏi ý kiến người ấy hoặc gia đình trước khi nêu tên.","hs":"- HS viết được câu chuyện ngắn trung thực đi kèm tranh của mình.\n- HS ghi đủ nguồn và tên tác giả trên sản phẩm chung của lớp."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 5, Tiết 4 - Trưng bày, thảo luận và vận dụng"},
{"lop":5,"mon":"Mĩ thuật","tuan":22,"tiet":22,"bai":"Chủ đề 6: Cảnh sắc quê hương (Tiết 1 - Quan sát, nhận biết)","yccd":"1. Năng lực mĩ thuật\n- Quan sát, nhận biết được vẻ đẹp tạo hình, hình ảnh, chất liệu liên quan đến chủ đề.\n- Nêu được cảm nhận ban đầu về đối tượng thẩm mĩ của chủ đề.\n- Có ý thức khai thác hình ảnh, chất liệu để chuẩn bị cho thực hành sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu quý, tự hào về cảnh sắc, vẻ đẹp của quê hương, đất nước.\n- Chăm chỉ, cẩn thận, có ý thức giữ gìn cảnh quan.\n4. Tích hợp\n- Năng lực số 1.1 CB2c: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS xác định được ba lớp cảnh gần, trung, xa nhờ xem địa hình từ nhiều góc.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề cảnh sắc quê hương.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (quan sát, nhận biết).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Quan sát, nhận biết","gv":"- GV cho HS quan sát hình minh hoạ trong SGK Mĩ thuật 5 và tư liệu GV chuẩn bị thêm về chủ đề cảnh sắc quê hương.\n- GV đặt câu hỏi gợi mở để HS nhận ra hình ảnh, chất liệu, cách thể hiện đặc trưng của chủ đề.\n- GV tóm tắt, bổ sung, khắc sâu nội dung Em có biết trong SGK.","hs":"- HS quan sát hình, tư liệu và trả lời câu hỏi.\n- HS nêu hiểu biết, cảm nhận ban đầu về chủ đề.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập - Chia sẻ hiểu biết","gv":"- GV cho HS kể thêm những hình ảnh, tác phẩm cùng chủ đề mà em biết.\n- GV định hướng HS lựa chọn hình ảnh sẽ khai thác cho phần thực hành ở tiết sau.","hs":"- HS chia sẻ trước lớp.\n- HS lựa chọn ý tưởng, hình ảnh cho sản phẩm của mình."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (quan sát, nhận biết).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS dùng bản đồ số và ảnh toàn cảnh xem lại một vùng của quê mình từ nhiều góc, nhận ra lớp cảnh gần, cảnh trung và cảnh xa; góc nhìn từ trên cao giúp HS hiểu bố cục của cảnh mà đứng dưới đất không hình dung được.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS ghi vào phiếu tư liệu ba lớp cảnh mình sẽ đưa vào tranh và nguồn của ảnh tham khảo.\n⚠ (Miền 4: An toàn) Chỉ tra cứu trong ứng dụng bản đồ GV chỉ định; không đánh dấu và không chia sẻ vị trí nhà mình hay nhà bạn; ảnh vệ tinh và ảnh toàn cảnh có bản quyền nên khi dùng phải ghi nguồn.","hs":"- HS xác định được ba lớp cảnh gần, trung, xa nhờ xem địa hình từ nhiều góc.\n- HS ghi được nguồn cho ảnh tham khảo."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 6, Tiết 1 - Quan sát, nhận biết"},
{"lop":5,"mon":"Mĩ thuật","tuan":23,"tiet":23,"bai":"Chủ đề 6: Cảnh sắc quê hương (Tiết 2 - Cách thực hiện sản phẩm)","yccd":"1. Năng lực mĩ thuật\n- Nêu được các bước cơ bản để thể hiện chủ đề thành sản phẩm mĩ thuật.\n- Lựa chọn được hình ảnh, chất liệu, cách thể hiện phù hợp với khả năng.\n- Biết vận dụng yếu tố và nguyên lí tạo hình đã học vào sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu quý, tự hào về cảnh sắc, vẻ đẹp của quê hương, đất nước.\n- Chăm chỉ, cẩn thận, có ý thức giữ gìn cảnh quan.","dodung":"- GV: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; 2-3 sản phẩm mẫu ở các mức độ khác nhau; bảng tiêu chí nhận xét sản phẩm viết sẵn; sao giấy màu cho HS bình chọn; nam châm, băng dính giấy để trưng bày; máy tính, máy chiếu và học liệu số.\n- HS: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; bút chì, tẩy, màu vẽ, giấy vẽ A4, giấy màu, kéo, keo dán, đất nặn.\n- Vật liệu thay thế khi lớp thiếu đồ dùng: giấy báo cũ, bìa carton, vỏ hộp sữa, lá cây khô, hột hạt, dây len, vải vụn, cúc áo, ống hút đã rửa sạch; đất nặn có thể thay bằng bột mì trộn muối và màu thực phẩm.\n- An toàn: dùng kéo đầu tròn, chuyền kéo quay mũi về phía mình; dao rọc giấy chỉ dùng khi có GV bên cạnh; keo, màu không đưa lên miệng; hết giờ thu gom giấy vụn, lau bàn, rửa tay.","hoatdong":[{"ten":"1. Khởi động","gv":"- (3 phút) GV chiếu 4 ảnh phong cảnh: cánh đồng, dòng sông, phố nhỏ, bãi biển; hỏi \"Cảnh nào giống nơi em ở nhất?\".\n- GV hỏi thêm: \"Trong ảnh, vật nào ở gần, vật nào ở xa?\" (dự kiến: cây và bờ ruộng ở gần, dãy núi và mây ở xa).\n- GV dẫn vào bài: tiết này lớp tìm hiểu cách thực hiện sản phẩm về cảnh sắc quê hương.","hs":"- HS quan sát ảnh, chọn cảnh gần gũi với nơi mình ở.\n- HS chỉ ra vật ở gần và vật ở xa trong ảnh.\n- HS nhắc lại nhiệm vụ tiết học."},{"ten":"2. Khám phá - Cách thực hiện","gv":"- (10 phút) GV cho HS quan sát các bước trong SGK Mĩ thuật 5 và hỏi: \"Vì sao phải vẽ đường chân trời trước khi vẽ cảnh vật?\".\n- Dự kiến HS đáp: để biết chỗ nào là bầu trời, chỗ nào là mặt đất, đặt cảnh vật cho đúng xa gần.\n- GV làm mẫu chậm cách tạo xa - gần: vật ở gần vẽ to, rõ chi tiết, màu đậm; vật ở xa vẽ nhỏ, ít chi tiết, màu nhạt và hơi ngả xanh.\n- GV mời 1-2 HS lên bảng vẽ thử một hàng cây ở xa và một cây ở gần, cả lớp nhận xét.","hs":"- HS quan sát các bước trong SGK và nêu lại thứ tự.\n- HS giải thích tác dụng của đường chân trời.\n- HS theo dõi mẫu, tập vẽ xa - gần ra giấy nháp.\n- HS lên bảng thao tác thử và nghe nhận xét."},{"ten":"3. Luyện tập - Thử phác ý tưởng","gv":"- (13 phút) GV cho HS phác hai phương án bố cục cảnh quê hương ra nháp rồi chọn một phương án ưng ý nhất.\n- GV gợi ý: chọn một hình ảnh chính như cây đa, con đò, mái đình, cánh đồng; thêm 2-3 hình phụ; đặt đường chân trời không nằm chính giữa tranh.\n- GV đi từng bàn hỏi: \"Cảnh của em vào buổi nào trong ngày?\" để HS chọn gam màu phù hợp.\n- GV nêu các lựa chọn chất liệu: vẽ màu, xé dán giấy màu, in lá cây hoặc ghép giấy báo, bìa carton, lá khô, hột hạt.","hs":"- HS phác hai phương án bố cục rồi chọn một.\n- HS xác định hình ảnh chính và vị trí đường chân trời.\n- HS chọn gam màu theo buổi trong ngày.\n- HS nêu chất liệu và vật liệu sẽ chuẩn bị."},{"ten":"4. Chia sẻ, góp ý phác thảo","gv":"- (6 phút) GV cho HS đổi nháp theo cặp, góp ý theo 3 câu hỏi: đã rõ hình ảnh chính chưa? đã tạo được xa - gần chưa? bố cục có bị chia đôi bằng nhau không?\n- GV chọn 2 phác thảo dán lên bảng, cùng lớp phân tích điểm được và chỗ cần chỉnh.\n- GV chốt tiêu chí cho tiết thực hành: hình ảnh chính rõ, bố cục cân đối và có xa - gần, màu hài hoà có đậm nhạt, bài sạch và có nét riêng.","hs":"- HS đổi nháp, góp ý cho bạn theo 3 câu hỏi.\n- HS nêu chỗ cần chỉnh trong phác thảo của mình.\n- HS ghi nhớ 4 tiêu chí đánh giá sản phẩm."},{"ten":"5. Vận dụng - Củng cố, dặn dò","gv":"- (3 phút) GV cùng HS nhắc lại các bước thực hiện sản phẩm theo đúng trình tự.\n- GV giao nhiệm vụ quan sát: trên đường về nhà chú ý một cảnh đẹp, nhớ hình dáng và màu sắc của cảnh đó.\n- GV nhận xét tiết học, nhắc cất đồ dùng gọn gàng; dặn tiết sau mang phác thảo, màu vẽ, giấy màu, kéo, keo và vật liệu tái sử dụng.","hs":"- HS nhắc lại các bước thực hiện sản phẩm.\n- HS nhận nhiệm vụ quan sát cảnh vật quê hương.\n- HS ghi rõ đồ dùng cần mang cho tiết thực hành."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 6, Tiết 2 - Cách thực hiện sản phẩm"},
{"lop":5,"mon":"Mĩ thuật","tuan":24,"tiet":24,"bai":"Chủ đề 6: Cảnh sắc quê hương (Tiết 3 - Thực hành, sáng tạo)","yccd":"1. Năng lực mĩ thuật\n- Tạo được sản phẩm mĩ thuật thể hiện nội dung chủ đề theo ý thích.\n- Vận dụng được hình, mảng, màu sắc, đậm nhạt, không gian để làm rõ nội dung.\n- Bước đầu thể hiện được sự sáng tạo và dấu ấn cá nhân trong sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu quý, tự hào về cảnh sắc, vẻ đẹp của quê hương, đất nước.\n- Chăm chỉ, cẩn thận, có ý thức giữ gìn cảnh quan.","dodung":"- GV: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; 2-3 sản phẩm mẫu ở các mức độ khác nhau; bảng tiêu chí nhận xét sản phẩm viết sẵn; sao giấy màu cho HS bình chọn; nam châm, băng dính giấy để trưng bày; máy tính, máy chiếu và học liệu số.\n- HS: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; bút chì, tẩy, màu vẽ, giấy vẽ A4, giấy màu, kéo, keo dán, đất nặn.\n- Vật liệu thay thế khi lớp thiếu đồ dùng: giấy báo cũ, bìa carton, vỏ hộp sữa, lá cây khô, hột hạt, dây len, vải vụn, cúc áo, ống hút đã rửa sạch; đất nặn có thể thay bằng bột mì trộn muối và màu thực phẩm.\n- An toàn: dùng kéo đầu tròn, chuyền kéo quay mũi về phía mình; dao rọc giấy chỉ dùng khi có GV bên cạnh; keo, màu không đưa lên miệng; hết giờ thu gom giấy vụn, lau bàn, rửa tay.","hoatdong":[{"ten":"1. Khởi động","gv":"- (3 phút) GV cho lớp chơi Kể tên cảnh đẹp: mỗi tổ nói một cảnh đẹp ở quê mình, không trùng nhau.\n- GV hỏi: \"Cảnh em vừa kể có màu gì là chính?\" (dự kiến: xanh của đồng lúa, vàng của nắng, nâu của mái nhà).\n- GV dẫn vào bài: tiết này các em hoàn thành sản phẩm cảnh sắc quê hương từ phác thảo tiết trước.","hs":"- HS thi kể tên cảnh đẹp ở quê hương.\n- HS nêu màu chủ đạo của cảnh mình kể.\n- HS lấy phác thảo và đồ dùng ra bàn."},{"ten":"2. Khám phá - Nhắc lại yêu cầu","gv":"- (6 phút) GV cho HS xem lại 2 sản phẩm mẫu và hỏi: \"Bài nào cho cảm giác cảnh vật sâu, rộng hơn? Nhờ đâu?\".\n- Dự kiến HS đáp: nhờ vật ở gần to và đậm, vật ở xa nhỏ và nhạt; nhờ có đường chân trời rõ ràng.\n- GV chốt 4 lưu ý: hình ảnh chính rõ; có lớp cảnh gần - xa; màu nền dịu để mảng chính nổi; chừa khoảng trống cho bầu trời hoặc mặt nước.\n- GV treo bảng tiêu chí nhận xét để HS biết trước đích cần đạt.","hs":"- HS quan sát, so sánh 2 sản phẩm mẫu và trả lời.\n- HS chỉ ra lớp cảnh ở gần và lớp cảnh ở xa.\n- HS nhắc lại 4 lưu ý trước khi thực hành.\n- HS đọc thầm bảng tiêu chí nhận xét."},{"ten":"3. Luyện tập - Thực hành, sáng tạo","gv":"- (18 phút) GV giao việc: HS hoàn thành sản phẩm từ phác thảo; nhóm 2-4 HS có thể ghép thành một bức tranh quê hương chung.\n- GV ghi các bước: 1) vẽ đường chân trời và mảng lớn; 2) vẽ hình ảnh chính; 3) thêm hình phụ ở xa; 4) tô màu bầu trời và mặt đất trước; 5) tạo đậm nhạt, làm nhạt dần cảnh ở xa; 6) hoàn thiện chi tiết, kí tên.\n- GV làm mẫu chậm bước 5: pha thêm chút màu trắng hoặc tô nhẹ tay cho cảnh ở xa, tô đậm và rõ chi tiết cho cảnh ở gần.\n- GV gợi ý HS thiếu màu dùng giấy báo, lá khô, hột hạt, vải vụn dán tạo mảng; nhắc an toàn khi dùng kéo, keo.","hs":"- HS làm bài theo 6 bước từ phác thảo đã chọn.\n- HS phân biệt rõ lớp cảnh ở gần và lớp cảnh ở xa.\n- HS tô nhạt dần cho cảnh ở xa để tạo chiều sâu.\n- HS dùng kéo, keo an toàn và giữ chỗ ngồi sạch sẽ."},{"ten":"4. Trưng bày, nhận xét sản phẩm","gv":"- (5 phút) GV cho HS ghép các bài thành một dải tranh dài trên bảng nhóm, đặt tên góc trưng bày là Quê hương em.\n- GV nêu tiêu chí: 1) rõ cảnh vật quê hương; 2) bố cục cân đối, có xa - gần; 3) màu hài hoà, có đậm nhạt; 4) bài sạch, có ý tưởng riêng.\n- GV cho HS tự đánh giá, đi xem, dán sao vào bài mình thích và nói \"Mình thích bài này vì...\"; GV nhận xét 2-3 bài theo tiêu chí.","hs":"- HS ghép bài thành dải tranh chung của nhóm.\n- HS tự đối chiếu bài mình với 4 tiêu chí.\n- HS dán sao và nhận xét bài bạn theo mẫu câu."},{"ten":"5. Vận dụng - Củng cố, dặn dò","gv":"- (3 phút) GV hỏi: em muốn giới thiệu cảnh đẹp nào của quê mình với một người bạn phương xa?\n- GV gợi ý dùng sản phẩm làm bưu thiếp hoặc trang trí góc Quê hương em của lớp.\n- GV nhận xét tiết học, nhắc giữ gìn cảnh quan nơi mình ở, thu giấy vụn, rửa tay; dặn tiết sau mang màu vẽ và tư liệu cho chủ đề mới.","hs":"- HS giới thiệu ngắn về cảnh đẹp quê mình.\n- HS nhận nhiệm vụ trang trí góc lớp.\n- HS dọn chỗ ngồi và ghi nhớ đồ dùng tiết sau."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 6, Tiết 3 - Thực hành, sáng tạo"},
{"lop":5,"mon":"Mĩ thuật","tuan":25,"tiet":25,"bai":"Chủ đề 6: Cảnh sắc quê hương (Tiết 4 - Trưng bày, thảo luận và vận dụng)","yccd":"1. Năng lực mĩ thuật\n- Trưng bày, giới thiệu và nêu được cảm nhận về sản phẩm của mình và của bạn.\n- Phân tích được vẻ đẹp, ý nghĩa của sản phẩm theo yếu tố, nguyên lí tạo hình.\n- Biết vận dụng kết quả học tập vào trang trí, làm đẹp cuộc sống.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu quý, tự hào về cảnh sắc, vẻ đẹp của quê hương, đất nước.\n- Chăm chỉ, cẩn thận, có ý thức giữ gìn cảnh quan.\n4. Tích hợp\n- Năng lực số 3.2 CB2a: Chọn được các cách sửa đổi, tinh chỉnh, cải thiện và tích hợp các mục đơn giản có nội dung và thông tin mới để tạo ra những nội dung và thông tin mới và độc đáo: HS hoàn thiện được phần thông tin cho tranh của mình trong triển lãm.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề cảnh sắc quê hương.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (trưng bày, thảo luận và vận dụng).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Chuẩn bị trưng bày","gv":"- GV hướng dẫn HS hoàn thiện, sắp xếp sản phẩm để trưng bày (theo cá nhân/nhóm).\n- GV gợi ý cách giới thiệu, nêu ý tưởng và cảm nhận về sản phẩm.","hs":"- HS hoàn thiện, sắp xếp sản phẩm.\n- HS chuẩn bị lời giới thiệu về sản phẩm của mình."},{"ten":"3. Luyện tập - Trưng bày, thảo luận","gv":"- GV tổ chức cho HS trưng bày, giới thiệu sản phẩm; gợi mở để HS phân tích, thảo luận về vẻ đẹp, ý nghĩa của sản phẩm.\n- GV nhận xét, đánh giá, ghi nhận sự tiến bộ và sáng tạo của HS.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS thảo luận, nhận xét sản phẩm của mình và của bạn."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV gợi ý HS vận dụng sản phẩm, kiến thức của chủ đề cảnh sắc quê hương vào trang trí, làm đẹp góc học tập, lớp học hoặc cuộc sống.\n- GV hệ thống nội dung chủ đề, nhận xét tiết học, tuyên dương; dặn HS chuẩn bị cho chủ đề sau.","hs":"- HS nêu cách vận dụng sản phẩm vào cuộc sống.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Lớp dựng trang triển lãm Cảnh sắc quê hương sắp xếp tranh theo vùng, mỗi tranh ghi tên địa danh, tên tác giả và chất liệu.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 2) HS đóng vai người xem triển lãm, đặt cho tác giả một câu hỏi về cách thể hiện lớp cảnh xa gần và tác giả trả lời.\n⚠ (Miền 4: An toàn) Ghi đủ tên tác giả và nguồn ảnh tham khảo; trang triển lãm chia sẻ trong trường, muốn đăng công khai phải được nhà trường và cha mẹ đồng ý.","hs":"- HS hoàn thiện được phần thông tin cho tranh của mình trong triển lãm.\n- HS đặt và trả lời được câu hỏi về cách thể hiện xa gần."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 6, Tiết 4 - Trưng bày, thảo luận và vận dụng"},
{"lop":5,"mon":"Mĩ thuật","tuan":26,"tiet":26,"bai":"Chủ đề 7: Việt Nam đất nước, con người (Tiết 1 - Quan sát, nhận biết)","yccd":"1. Năng lực mĩ thuật\n- Quan sát, nhận biết được vẻ đẹp tạo hình, hình ảnh, chất liệu liên quan đến chủ đề.\n- Nêu được cảm nhận ban đầu về đối tượng thẩm mĩ của chủ đề.\n- Có ý thức khai thác hình ảnh, chất liệu để chuẩn bị cho thực hành sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu quý, tự hào về đất nước, con người và bản sắc văn hoá Việt Nam.\n- Chăm chỉ, có trách nhiệm với cộng đồng.\n4. Tích hợp\n- Năng lực số 1.1 CB2c: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS đối chiếu được hai nguồn và gọi đúng tên dân tộc, vùng miền.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề việt Nam đất nước, con người.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (quan sát, nhận biết).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Quan sát, nhận biết","gv":"- GV cho HS quan sát hình minh hoạ trong SGK Mĩ thuật 5 và tư liệu GV chuẩn bị thêm về chủ đề việt Nam đất nước, con người.\n- GV đặt câu hỏi gợi mở để HS nhận ra hình ảnh, chất liệu, cách thể hiện đặc trưng của chủ đề.\n- GV tóm tắt, bổ sung, khắc sâu nội dung Em có biết trong SGK.","hs":"- HS quan sát hình, tư liệu và trả lời câu hỏi.\n- HS nêu hiểu biết, cảm nhận ban đầu về chủ đề.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập - Chia sẻ hiểu biết","gv":"- GV cho HS kể thêm những hình ảnh, tác phẩm cùng chủ đề mà em biết.\n- GV định hướng HS lựa chọn hình ảnh sẽ khai thác cho phần thực hành ở tiết sau.","hs":"- HS chia sẻ trước lớp.\n- HS lựa chọn ý tưởng, hình ảnh cho sản phẩm của mình."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (quan sát, nhận biết).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS tìm tư liệu về trang phục, lễ hội, kiến trúc của một vùng miền trên trang của bảo tàng và cổng thông tin địa phương, đối chiếu ít nhất hai nguồn để tránh nhầm lẫn trang phục giữa các dân tộc.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS lập phiếu tư liệu ghi tên vùng miền, dân tộc, chi tiết đặc trưng và nguồn của từng thông tin.\n⚠ (Miền 4: An toàn) Trang phục và hoa văn của mỗi dân tộc gắn với văn hoá của cộng đồng ấy nên vẽ sai hoặc gán nhầm cho dân tộc khác là thiếu tôn trọng; ảnh tư liệu phải ghi rõ nguồn, không dùng ảnh do máy tạo làm căn cứ vì máy hay trộn lẫn đặc điểm các dân tộc.","hs":"- HS đối chiếu được hai nguồn và gọi đúng tên dân tộc, vùng miền.\n- HS lập được phiếu tư liệu ghi rõ nguồn."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 7, Tiết 1 - Quan sát, nhận biết"},
{"lop":5,"mon":"Mĩ thuật","tuan":27,"tiet":27,"bai":"Chủ đề 7: Việt Nam đất nước, con người (Tiết 2 - Cách thực hiện sản phẩm)","yccd":"1. Năng lực mĩ thuật\n- Nêu được các bước cơ bản để thể hiện chủ đề thành sản phẩm mĩ thuật.\n- Lựa chọn được hình ảnh, chất liệu, cách thể hiện phù hợp với khả năng.\n- Biết vận dụng yếu tố và nguyên lí tạo hình đã học vào sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu quý, tự hào về đất nước, con người và bản sắc văn hoá Việt Nam.\n- Chăm chỉ, có trách nhiệm với cộng đồng.\n4. Tích hợp\n- Năng lực số 3.1 CB2a: Xác định được các cách tạo và chỉnh sửa nội dung đơn giản ở các định dạng đơn giản: HS dựng được dải hoa văn đối xứng bằng lệnh sao chép và lật hình.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề việt Nam đất nước, con người.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (tìm hiểu cách thực hiện).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Cách thực hiện","gv":"- GV hướng dẫn HS phân tích các bước thực hiện sản phẩm trong SGK Mĩ thuật 5 (khai thác nội dung chủ đề việt Nam đất nước, con người).\n- GV làm mẫu hoặc mời HS lên thao tác thử một số bước; lưu ý cách chọn hình ảnh, chất liệu phù hợp.","hs":"- HS quan sát, phân tích các bước thực hiện.\n- HS nêu lại các bước và ghi nhớ."},{"ten":"3. Luyện tập - Thử phác ý tưởng","gv":"- GV cho HS phác nhanh ý tưởng, bố cục cho sản phẩm của mình.\n- GV quan sát, gợi ý điều chỉnh để HS chuẩn bị tốt cho tiết thực hành.","hs":"- HS phác ý tưởng, lựa chọn cách thể hiện.\n- HS chuẩn bị chất liệu phù hợp."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (tìm hiểu cách thực hiện).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) HS dùng ứng dụng vẽ tạo một hoạ tiết đặc trưng của vùng miền mình chọn rồi dùng lệnh sao chép và lật hình để dựng thành dải hoa văn đối xứng; máy giúp thấy ngay hiệu quả của sự lặp lại và đối xứng trước khi vẽ tay.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 2) GV nhập tên một loại hoa văn dân tộc vào công cụ tạo hình bằng trí tuệ nhân tạo cho máy sinh vài mẫu; HS đối chiếu với ảnh tư liệu thật, chỉ ra chỗ máy vẽ sai và giải thích vì sao máy dễ nhầm hoa văn của các dân tộc với nhau.\n⚠ (Miền 4: An toàn) Mẫu do máy sinh chỉ dùng để so sánh và phê phán, không đưa vào sản phẩm rồi giới thiệu là hoa văn của một dân tộc vì làm vậy là truyền đi thông tin sai về văn hoá của họ; GV thao tác công cụ, HS không dùng tài khoản riêng.","hs":"- HS dựng được dải hoa văn đối xứng bằng lệnh sao chép và lật hình.\n- HS chỉ ra được chỗ sai của mẫu hoa văn do máy sinh và nêu được lí do."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 7, Tiết 2 - Cách thực hiện sản phẩm"},
{"lop":5,"mon":"Mĩ thuật","tuan":28,"tiet":28,"bai":"Chủ đề 7: Việt Nam đất nước, con người (Tiết 3 - Thực hành, sáng tạo)","yccd":"1. Năng lực mĩ thuật\n- Tạo được sản phẩm mĩ thuật thể hiện nội dung chủ đề theo ý thích.\n- Vận dụng được hình, mảng, màu sắc, đậm nhạt, không gian để làm rõ nội dung.\n- Bước đầu thể hiện được sự sáng tạo và dấu ấn cá nhân trong sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu quý, tự hào về đất nước, con người và bản sắc văn hoá Việt Nam.\n- Chăm chỉ, có trách nhiệm với cộng đồng.","dodung":"- GV: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; 2-3 sản phẩm mẫu ở các mức độ khác nhau; bảng tiêu chí nhận xét sản phẩm viết sẵn; sao giấy màu cho HS bình chọn; nam châm, băng dính giấy để trưng bày; máy tính, máy chiếu và học liệu số.\n- HS: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; bút chì, tẩy, màu vẽ, giấy vẽ A4, giấy màu, kéo, keo dán, đất nặn.\n- Vật liệu thay thế khi lớp thiếu đồ dùng: giấy báo cũ, bìa carton, vỏ hộp sữa, lá cây khô, hột hạt, dây len, vải vụn, cúc áo, ống hút đã rửa sạch; đất nặn có thể thay bằng bột mì trộn muối và màu thực phẩm.\n- An toàn: dùng kéo đầu tròn, chuyền kéo quay mũi về phía mình; dao rọc giấy chỉ dùng khi có GV bên cạnh; keo, màu không đưa lên miệng; hết giờ thu gom giấy vụn, lau bàn, rửa tay.","hoatdong":[{"ten":"1. Khởi động","gv":"- (3 phút) GV chiếu 4 hình: Chùa Một Cột, vịnh Hạ Long, tà áo dài, chiếc nón lá và tổ chức trò chơi Đố nhanh tên hình ảnh.\n- GV hỏi: \"Hình ảnh nào làm em nhớ ngay đến Việt Nam?\" (dự kiến: nón lá, áo dài, cây tre, trống đồng, cánh đồng lúa).\n- GV dẫn vào bài: tiết này các em hoàn thành sản phẩm về đất nước, con người Việt Nam.","hs":"- HS đoán nhanh tên các hình ảnh quen thuộc.\n- HS nêu hình ảnh gợi nhớ đến Việt Nam.\n- HS bày phác thảo và đồ dùng lên bàn."},{"ten":"2. Khám phá - Nhắc lại yêu cầu","gv":"- (6 phút) GV cho HS xem lại sản phẩm mẫu và hỏi: \"Sản phẩm này giới thiệu điều gì về đất nước ta?\".\n- Dự kiến HS đáp: cảnh đẹp, trang phục dân tộc, lễ hội, món ăn, con người đang lao động.\n- GV chốt: chọn một hình ảnh tiêu biểu làm hình chính; thêm hoa văn, hoạ tiết dân tộc trang trí; dùng màu tươi sáng, có đậm nhạt cho hình chính nổi rõ.\n- GV treo bảng tiêu chí nhận xét để HS biết trước đích cần đạt.","hs":"- HS quan sát mẫu và nêu nội dung nhận ra.\n- HS chọn hình ảnh tiêu biểu cho bài của mình.\n- HS nhắc lại lưu ý về hình chính và hoạ tiết.\n- HS đọc thầm bảng tiêu chí nhận xét."},{"ten":"3. Luyện tập - Thực hành, sáng tạo","gv":"- (18 phút) GV giao việc: mỗi HS hoàn thành sản phẩm giới thiệu một nét đẹp của đất nước, con người Việt Nam; nhóm 2-4 HS có thể ghép thành một bức lớn.\n- GV ghi các bước: 1) phác bố cục, đặt hình ảnh chính; 2) vẽ hoặc cắt hình chính; 3) thêm hình phụ và hoạ tiết trang trí; 4) tô màu mảng lớn; 5) tạo đậm nhạt cho nổi hình chính; 6) hoàn thiện, kí tên.\n- GV làm mẫu chậm bước 3: vẽ lặp lại một hoạ tiết theo hàng để viền tranh cho đều và cân đối.\n- GV gợi ý HS thiếu đồ dùng dùng giấy báo, bìa carton, lá khô, hột hạt, dây len tạo hoa văn; nhắc an toàn khi cắt dán.","hs":"- HS làm bài theo 6 bước đã hướng dẫn.\n- HS chọn và thể hiện rõ hình ảnh tiêu biểu của đất nước.\n- HS trang trí hoạ tiết lặp lại đều tay ở viền tranh.\n- HS dùng kéo, keo an toàn và giữ bàn ghế sạch sẽ."},{"ten":"4. Trưng bày, nhận xét sản phẩm","gv":"- (5 phút) GV cho HS dán bài lên bảng nhóm theo nhóm nội dung: cảnh đẹp, lễ hội, trang phục, con người.\n- GV nêu tiêu chí: 1) rõ nét đẹp Việt Nam được giới thiệu; 2) bố cục cân đối, hình chính rõ; 3) màu hài hoà, có đậm nhạt; 4) bài sạch, có ý tưởng riêng.\n- GV cho HS tự đánh giá, đi xem phòng tranh, dán sao và nói \"Mình thích bài này vì...\"; GV nhận xét 2-3 bài theo tiêu chí.","hs":"- HS trưng bày bài đúng nhóm nội dung.\n- HS tự đối chiếu bài mình với 4 tiêu chí.\n- HS dán sao, nhận xét bài bạn và giới thiệu bài của mình."},{"ten":"5. Vận dụng - Củng cố, dặn dò","gv":"- (3 phút) GV hỏi: nếu gặp một người bạn nước ngoài, em sẽ giới thiệu điều gì về Việt Nam?\n- GV gợi ý dùng sản phẩm làm bìa tập san hoặc trang trí góc Đất nước em của lớp.\n- GV nhận xét tiết học, tuyên dương HS có ý tưởng riêng; nhắc thu giấy vụn, rửa tay; dặn tiết sau mang màu vẽ và giấy màu cho chủ đề mới.","hs":"- HS nói điều mình muốn giới thiệu về đất nước.\n- HS nhận nhiệm vụ trang trí góc lớp.\n- HS dọn chỗ ngồi và ghi nhớ đồ dùng tiết sau."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 7, Tiết 3 - Thực hành, sáng tạo"},
{"lop":5,"mon":"Mĩ thuật","tuan":29,"tiet":29,"bai":"Chủ đề 7: Việt Nam đất nước, con người (Tiết 4 - Trưng bày, thảo luận và vận dụng)","yccd":"1. Năng lực mĩ thuật\n- Trưng bày, giới thiệu và nêu được cảm nhận về sản phẩm của mình và của bạn.\n- Phân tích được vẻ đẹp, ý nghĩa của sản phẩm theo yếu tố, nguyên lí tạo hình.\n- Biết vận dụng kết quả học tập vào trang trí, làm đẹp cuộc sống.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu quý, tự hào về đất nước, con người và bản sắc văn hoá Việt Nam.\n- Chăm chỉ, có trách nhiệm với cộng đồng.\n4. Tích hợp\n- Năng lực số 2.2 CB2a: Nhận biết được các công nghệ số đơn giản, phù hợp để chia sẻ dữ liệu, thông tin và nội dung số: HS lập được danh mục nguồn cho trang trưng bày của lớp.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề việt Nam đất nước, con người.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (trưng bày, thảo luận và vận dụng).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Chuẩn bị trưng bày","gv":"- GV hướng dẫn HS hoàn thiện, sắp xếp sản phẩm để trưng bày (theo cá nhân/nhóm).\n- GV gợi ý cách giới thiệu, nêu ý tưởng và cảm nhận về sản phẩm.","hs":"- HS hoàn thiện, sắp xếp sản phẩm.\n- HS chuẩn bị lời giới thiệu về sản phẩm của mình."},{"ten":"3. Luyện tập - Trưng bày, thảo luận","gv":"- GV tổ chức cho HS trưng bày, giới thiệu sản phẩm; gợi mở để HS phân tích, thảo luận về vẻ đẹp, ý nghĩa của sản phẩm.\n- GV nhận xét, đánh giá, ghi nhận sự tiến bộ và sáng tạo của HS.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS thảo luận, nhận xét sản phẩm của mình và của bạn."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV gợi ý HS vận dụng sản phẩm, kiến thức của chủ đề việt Nam đất nước, con người vào trang trí, làm đẹp góc học tập, lớp học hoặc cuộc sống.\n- GV hệ thống nội dung chủ đề, nhận xét tiết học, tuyên dương; dặn HS chuẩn bị cho chủ đề sau.","hs":"- HS nêu cách vận dụng sản phẩm vào cuộc sống.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 2) Lớp dựng trang trưng bày Việt Nam đất nước, con người xếp theo vùng miền; mỗi HS thuyết minh ngắn về vùng miền mình thể hiện cho các bạn nghe.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) HS ghi ở cuối trang danh mục nguồn tư liệu và tên tác giả của từng tác phẩm.\n⚠ (Miền 4: An toàn) Thuyết minh phải đúng với tư liệu, không nói theo cảm tính về phong tục của dân tộc khác; ghi đủ nguồn; chỉ chia sẻ trong phạm vi nhà trường.","hs":"- HS thuyết minh được về vùng miền mình thể hiện dựa trên tư liệu.\n- HS lập được danh mục nguồn cho trang trưng bày của lớp."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 7, Tiết 4 - Trưng bày, thảo luận và vận dụng"},
{"lop":5,"mon":"Mĩ thuật","tuan":30,"tiet":30,"bai":"Chủ đề 8: Vì một thế giới hoà bình (Tiết 1 - Quan sát, nhận biết)","yccd":"1. Năng lực mĩ thuật\n- Quan sát, nhận biết được vẻ đẹp tạo hình, hình ảnh, chất liệu liên quan đến chủ đề.\n- Nêu được cảm nhận ban đầu về đối tượng thẩm mĩ của chủ đề.\n- Có ý thức khai thác hình ảnh, chất liệu để chuẩn bị cho thực hành sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu hoà bình, có ý thức chia sẻ, thân thiện với mọi người.\n- Chăm chỉ, nhân ái, có trách nhiệm với cộng đồng.\n4. Tích hợp\n- Năng lực số 1.1 CB2c: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS giải thích được ý nghĩa của một biểu tượng hoà bình trong mĩ thuật.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề vì một thế giới hoà bình.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (quan sát, nhận biết).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Quan sát, nhận biết","gv":"- GV cho HS quan sát hình minh hoạ trong SGK Mĩ thuật 5 và tư liệu GV chuẩn bị thêm về chủ đề vì một thế giới hoà bình.\n- GV đặt câu hỏi gợi mở để HS nhận ra hình ảnh, chất liệu, cách thể hiện đặc trưng của chủ đề.\n- GV tóm tắt, bổ sung, khắc sâu nội dung Em có biết trong SGK.","hs":"- HS quan sát hình, tư liệu và trả lời câu hỏi.\n- HS nêu hiểu biết, cảm nhận ban đầu về chủ đề.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập - Chia sẻ hiểu biết","gv":"- GV cho HS kể thêm những hình ảnh, tác phẩm cùng chủ đề mà em biết.\n- GV định hướng HS lựa chọn hình ảnh sẽ khai thác cho phần thực hành ở tiết sau.","hs":"- HS chia sẻ trước lớp.\n- HS lựa chọn ý tưởng, hình ảnh cho sản phẩm của mình."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (quan sát, nhận biết).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS xem các tác phẩm mĩ thuật Việt Nam và thế giới về đề tài hoà bình như chim bồ câu, vòng tay, cánh đồng, trẻ em, tìm hiểu vì sao mỗi hình ảnh trở thành biểu tượng và đọc chú thích để biết tác giả, năm sáng tác.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS chọn một biểu tượng, ghi lại ý nghĩa của nó và tên tác phẩm đã dùng biểu tượng ấy.\n⚠ (Miền 4: An toàn) Biểu tượng hoà bình được nhiều tác giả sử dụng nên HS học cách dùng biểu tượng chứ không sao chép nguyên tác phẩm của một tác giả cụ thể; mọi hình tham khảo đều phải ghi tên tác giả.","hs":"- HS giải thích được ý nghĩa của một biểu tượng hoà bình trong mĩ thuật.\n- HS phân biệt được việc học cách dùng biểu tượng với việc chép tác phẩm."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 8, Tiết 1 - Quan sát, nhận biết"},
{"lop":5,"mon":"Mĩ thuật","tuan":31,"tiet":31,"bai":"Chủ đề 8: Vì một thế giới hoà bình (Tiết 2 - Cách thực hiện sản phẩm)","yccd":"1. Năng lực mĩ thuật\n- Nêu được các bước cơ bản để thể hiện chủ đề thành sản phẩm mĩ thuật.\n- Lựa chọn được hình ảnh, chất liệu, cách thể hiện phù hợp với khả năng.\n- Biết vận dụng yếu tố và nguyên lí tạo hình đã học vào sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu hoà bình, có ý thức chia sẻ, thân thiện với mọi người.\n- Chăm chỉ, nhân ái, có trách nhiệm với cộng đồng.\n4. Tích hợp\n- Năng lực số 3.2 CB2a: Chọn được các cách sửa đổi, tinh chỉnh, cải thiện và tích hợp các mục đơn giản có nội dung và thông tin mới để tạo ra những nội dung và thông tin mới và độc đáo: HS chỉnh sửa được sản phẩm dựa trên kết quả tự kiểm tra.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề vì một thế giới hoà bình.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (tìm hiểu cách thực hiện).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Cách thực hiện","gv":"- GV hướng dẫn HS phân tích các bước thực hiện sản phẩm trong SGK Mĩ thuật 5 (khai thác nội dung chủ đề vì một thế giới hoà bình).\n- GV làm mẫu hoặc mời HS lên thao tác thử một số bước; lưu ý cách chọn hình ảnh, chất liệu phù hợp.","hs":"- HS quan sát, phân tích các bước thực hiện.\n- HS nêu lại các bước và ghi nhớ."},{"ten":"3. Luyện tập - Thử phác ý tưởng","gv":"- GV cho HS phác nhanh ý tưởng, bố cục cho sản phẩm của mình.\n- GV quan sát, gợi ý điều chỉnh để HS chuẩn bị tốt cho tiết thực hành.","hs":"- HS phác ý tưởng, lựa chọn cách thể hiện.\n- HS chuẩn bị chất liệu phù hợp."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (tìm hiểu cách thực hiện).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) HS thiết kế bố cục tranh cổ động hoà bình trên phần mềm trình chiếu: đặt khối hình chính, chọn cỡ chữ khẩu hiệu, thử hai phương án màu nền, sau đó thu nhỏ trang chiếu để kiểm tra khẩu hiệu còn đọc được từ xa hay không.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS chỉnh lại bố cục và cỡ chữ dựa trên kết quả tự kiểm tra rồi thể hiện tranh bằng chất liệu thật.\n⚠ (Miền 4: An toàn) Khẩu hiệu do HS tự nghĩ, nếu mượn một câu đã có thì phải ghi rõ câu ấy của ai; lưu tệp vào thư mục của mình và không sửa tệp của bạn.","hs":"- HS thiết kế và tự kiểm tra được bố cục, cỡ chữ của tranh cổ động.\n- HS chỉnh sửa được sản phẩm dựa trên kết quả tự kiểm tra."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 8, Tiết 2 - Cách thực hiện sản phẩm"},
{"lop":5,"mon":"Mĩ thuật","tuan":32,"tiet":32,"bai":"Chủ đề 8: Vì một thế giới hoà bình (Tiết 3 - Thực hành, sáng tạo)","yccd":"1. Năng lực mĩ thuật\n- Tạo được sản phẩm mĩ thuật thể hiện nội dung chủ đề theo ý thích.\n- Vận dụng được hình, mảng, màu sắc, đậm nhạt, không gian để làm rõ nội dung.\n- Bước đầu thể hiện được sự sáng tạo và dấu ấn cá nhân trong sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu hoà bình, có ý thức chia sẻ, thân thiện với mọi người.\n- Chăm chỉ, nhân ái, có trách nhiệm với cộng đồng.","dodung":"- GV: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; 2-3 sản phẩm mẫu ở các mức độ khác nhau; bảng tiêu chí nhận xét sản phẩm viết sẵn; sao giấy màu cho HS bình chọn; nam châm, băng dính giấy để trưng bày; máy tính, máy chiếu và học liệu số.\n- HS: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; bút chì, tẩy, màu vẽ, giấy vẽ A4, giấy màu, kéo, keo dán, đất nặn.\n- Vật liệu thay thế khi lớp thiếu đồ dùng: giấy báo cũ, bìa carton, vỏ hộp sữa, lá cây khô, hột hạt, dây len, vải vụn, cúc áo, ống hút đã rửa sạch; đất nặn có thể thay bằng bột mì trộn muối và màu thực phẩm.\n- An toàn: dùng kéo đầu tròn, chuyền kéo quay mũi về phía mình; dao rọc giấy chỉ dùng khi có GV bên cạnh; keo, màu không đưa lên miệng; hết giờ thu gom giấy vụn, lau bàn, rửa tay.","hoatdong":[{"ten":"1. Khởi động","gv":"- (3 phút) GV chiếu hình chim bồ câu, cành ô liu, quả địa cầu, trẻ em nắm tay nhau và hỏi: \"Những hình này nhắc em nghĩ tới điều gì?\".\n- Dự kiến HS đáp: hoà bình, tình bạn, không có chiến tranh, mọi người yêu thương nhau.\n- GV dẫn vào bài: tiết này các em hoàn thành sản phẩm gửi thông điệp vì một thế giới hoà bình.","hs":"- HS quan sát hình và nêu điều mình nghĩ tới.\n- HS kể thêm hình ảnh tượng trưng cho hoà bình.\n- HS bày phác thảo và đồ dùng lên bàn."},{"ten":"2. Khám phá - Nhắc lại yêu cầu","gv":"- (6 phút) GV cho HS xem lại sản phẩm mẫu và hỏi: \"Người xem hiểu được thông điệp gì từ bài này? Nhờ hình ảnh nào?\".\n- Dự kiến HS đáp: nhờ chim bồ câu, bàn tay nắm nhau, vòng tròn trẻ em quanh quả địa cầu.\n- GV chốt: chọn 1-2 hình ảnh tượng trưng làm hình chính; sắp xếp cân đối; dùng màu tươi sáng, có đậm nhạt để hình chính nổi rõ.\n- GV treo bảng tiêu chí nhận xét để HS biết trước đích cần đạt.","hs":"- HS quan sát mẫu, nêu thông điệp mình nhận ra.\n- HS chọn hình ảnh tượng trưng cho bài của mình.\n- HS nhắc lại lưu ý về bố cục và màu sắc.\n- HS đọc thầm bảng tiêu chí nhận xét."},{"ten":"3. Luyện tập - Thực hành, sáng tạo","gv":"- (18 phút) GV giao việc: mỗi HS hoàn thành sản phẩm về chủ đề hoà bình; nhóm 2-4 HS có thể làm chung một bức tranh cổ động khổ lớn.\n- GV ghi các bước: 1) phác bố cục, đặt hình ảnh chính; 2) vẽ hoặc cắt hình chính; 3) thêm hình phụ và dòng chữ ngắn; 4) tô màu mảng lớn trước; 5) tạo đậm nhạt để hình chính nổi; 6) hoàn thiện, kí tên.\n- GV làm mẫu chậm bước 3: kẻ chữ đều tay, chữ to vừa phải, đặt ở khoảng trống chứ không đè lên hình chính.\n- GV gợi ý HS thiếu màu dùng giấy báo, giấy màu, vải vụn, dây len ghép hình; nhắc an toàn khi dùng kéo và keo.","hs":"- HS làm bài theo 6 bước đã hướng dẫn.\n- HS chọn hình ảnh tượng trưng rõ ý cho thông điệp.\n- HS kẻ dòng chữ ngắn đều tay, đặt ở khoảng trống.\n- HS dùng kéo, keo an toàn và giữ chỗ ngồi sạch sẽ."},{"ten":"4. Trưng bày, nhận xét sản phẩm","gv":"- (5 phút) GV cho HS dán bài lên bảng nhóm, tạo phòng tranh mini mang tên Vì một thế giới hoà bình.\n- GV nêu tiêu chí: 1) truyền được thông điệp hoà bình; 2) bố cục cân đối, hình chính rõ; 3) màu hài hoà, có đậm nhạt; 4) bài sạch, có ý tưởng riêng.\n- GV cho HS tự đánh giá, đi xem, dán sao vào bài mình thích và nói \"Mình thích bài này vì...\"; GV nhận xét 2-3 bài theo tiêu chí.","hs":"- HS trưng bày bài và đọc thông điệp của mình.\n- HS tự đối chiếu bài mình với 4 tiêu chí.\n- HS dán sao và nhận xét bài bạn theo mẫu câu."},{"ten":"5. Vận dụng - Củng cố, dặn dò","gv":"- (3 phút) GV hỏi: ở lớp mình, em làm gì để giữ không khí hoà thuận, thân thiện?\n- GV gợi ý dùng sản phẩm làm tranh cổ động treo ở hành lang hoặc gửi dự thi vẽ tranh của trường.\n- GV nhận xét tiết học, nhắc thu giấy vụn, lau bàn, rửa tay; dặn tiết sau ôn lại các chủ đề đã học để chuẩn bị kiểm tra cuối năm.","hs":"- HS nêu việc làm giữ hoà thuận trong lớp.\n- HS nhận nhiệm vụ treo tranh cổ động ở hành lang.\n- HS dọn chỗ ngồi và ghi nhớ việc ôn tập cuối năm."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 8, Tiết 3 - Thực hành, sáng tạo"},
{"lop":5,"mon":"Mĩ thuật","tuan":33,"tiet":33,"bai":"Chủ đề 8: Vì một thế giới hoà bình (Tiết 4 - Trưng bày, thảo luận và vận dụng)","yccd":"1. Năng lực mĩ thuật\n- Trưng bày, giới thiệu và nêu được cảm nhận về sản phẩm của mình và của bạn.\n- Phân tích được vẻ đẹp, ý nghĩa của sản phẩm theo yếu tố, nguyên lí tạo hình.\n- Biết vận dụng kết quả học tập vào trang trí, làm đẹp cuộc sống.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu hoà bình, có ý thức chia sẻ, thân thiện với mọi người.\n- Chăm chỉ, nhân ái, có trách nhiệm với cộng đồng.\n4. Tích hợp\n- Năng lực số 3.3 CB2a: Xác định được các quy tắc đơn giản về bản quyền và giấy phép áp dụng cho dữ liệu, thông tin và nội dung số: HS ghi đủ tên tác giả và nguồn trên sản phẩm chung.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề vì một thế giới hoà bình.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (trưng bày, thảo luận và vận dụng).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Chuẩn bị trưng bày","gv":"- GV hướng dẫn HS hoàn thiện, sắp xếp sản phẩm để trưng bày (theo cá nhân/nhóm).\n- GV gợi ý cách giới thiệu, nêu ý tưởng và cảm nhận về sản phẩm.","hs":"- HS hoàn thiện, sắp xếp sản phẩm.\n- HS chuẩn bị lời giới thiệu về sản phẩm của mình."},{"ten":"3. Luyện tập - Trưng bày, thảo luận","gv":"- GV tổ chức cho HS trưng bày, giới thiệu sản phẩm; gợi mở để HS phân tích, thảo luận về vẻ đẹp, ý nghĩa của sản phẩm.\n- GV nhận xét, đánh giá, ghi nhận sự tiến bộ và sáng tạo của HS.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS thảo luận, nhận xét sản phẩm của mình và của bạn."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV gợi ý HS vận dụng sản phẩm, kiến thức của chủ đề vì một thế giới hoà bình vào trang trí, làm đẹp góc học tập, lớp học hoặc cuộc sống.\n- GV hệ thống nội dung chủ đề, nhận xét tiết học, tuyên dương; dặn HS chuẩn bị cho chủ đề sau.","hs":"- HS nêu cách vận dụng sản phẩm vào cuộc sống.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 2) Lớp lập trang trưng bày tranh cổ động hoà bình kèm khẩu hiệu và giới thiệu trong buổi sinh hoạt dưới cờ; HS tập nói lời giới thiệu ngắn, rõ thông điệp.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) HS ghi tên tác giả cho từng tranh và ghi nguồn cho mọi câu trích dẫn, hình ảnh tham khảo.\n⚠ (Miền 4: An toàn) Thông điệp hoà bình phải rõ ràng, không dùng hình ảnh bạo lực gây sợ hãi cho các em nhỏ hơn; chỉ chia sẻ trong nhà trường, đăng rộng hơn phải được nhà trường đồng ý.","hs":"- HS giới thiệu được tranh cổ động của mình với thông điệp rõ ràng.\n- HS ghi đủ tên tác giả và nguồn trên sản phẩm chung."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 8, Tiết 4 - Trưng bày, thảo luận và vận dụng"},
{"lop":5,"mon":"Mĩ thuật","tuan":34,"tiet":34,"bai":"Kiểm tra, đánh giá cuối năm học","yccd":"1. Năng lực mĩ thuật\n- Vận dụng kiến thức, kĩ năng đã học trong năm để hoàn thành một sản phẩm mĩ thuật theo yêu cầu.\n- Thể hiện được yếu tố, nguyên lí tạo hình phù hợp nội dung; có ý tưởng và dấu ấn cá nhân.\n- Giới thiệu và nêu được cảm nhận về sản phẩm của mình.\n2. Năng lực chung\n- Tự chủ và tự học; giải quyết vấn đề và sáng tạo khi hoàn thành sản phẩm.\n3. Phẩm chất\n- Chăm chỉ, trung thực, có trách nhiệm; tự tin thể hiện sản phẩm của mình.","dodung":"- GV: đề bài thực hành và bảng tiêu chí đánh giá viết sẵn trên giấy khổ lớn; một vài sản phẩm mẫu để HS hình dung mức cần đạt; giấy vẽ, màu dự phòng cho HS quên đồ dùng; phiếu tự đánh giá; sao giấy màu, nam châm, băng dính giấy để trưng bày; thiết bị trình chiếu học liệu số.\n- HS: đồ dùng học tập môn Mĩ thuật; giấy vẽ, bút chì, tẩy, màu vẽ, giấy màu, kéo, keo dán và chất liệu đã chuẩn bị.\n- Vật liệu thay thế khi thiếu đồ dùng: giấy báo cũ, bìa carton, vỏ hộp, lá cây khô, hột hạt, dây len, vải vụn để cắt dán hoặc tạo hình nổi.\n- An toàn: dùng kéo đầu tròn, không đùa nghịch khi cầm kéo; keo, màu không đưa lên miệng; làm xong thu gom giấy vụn, lau bàn ghế và rửa tay sạch.","hoatdong":[{"ten":"1. Khởi động - Nêu yêu cầu và tiêu chí","gv":"- (4 phút) GV ổn định lớp, nêu mục đích tiết kiểm tra, đánh giá cuối năm học: mỗi HS hoàn thành một sản phẩm mĩ thuật theo chủ đề đã học trong năm.\n- GV ghi đề lên bảng, cho HS chọn một chủ đề đã học như gia đình, trường học, việc tốt, quê hương, đất nước con người hoặc hoà bình.\n- GV treo bảng tiêu chí và giải thích: 1) đúng chủ đề, có hình ảnh chính rõ; 2) bố cục cân đối, có hình phụ và nền; 3) màu hài hoà, có đậm nhạt; 4) hoàn thiện sạch sẽ, có ý tưởng riêng.\n- GV nhắc HS chọn chất liệu vừa sức: vẽ màu, xé dán giấy hoặc ghép vật liệu tái sử dụng như bìa carton, giấy báo, lá khô, vải vụn, hột hạt.","hs":"- HS lắng nghe, nắm mục đích và yêu cầu của tiết kiểm tra cuối năm.\n- HS chọn một chủ đề đã học trong năm để thể hiện.\n- HS đọc lại 4 tiêu chí, hỏi lại GV chỗ mình chưa rõ.\n- HS chuẩn bị giấy, màu và chất liệu phù hợp với khả năng của mình."},{"ten":"2. Thực hành, kiểm tra","gv":"- (20 phút) GV cho HS làm bài độc lập, gợi ý chia thời gian: 5 phút phác bố cục, 10 phút vẽ hình và tô màu, 5 phút hoàn thiện.\n- GV ghi các bước lên bảng: 1) phác bố cục bằng nét chì mờ; 2) vẽ hình ảnh chính; 3) thêm hình phụ và nền; 4) tô màu mảng lớn trước; 5) tạo đậm nhạt cho rõ trọng tâm; 6) tẩy nét thừa, kí tên.\n- GV bao quát lớp, báo thời gian ở phút thứ 10 và phút thứ 17; chuẩn bị giấy, màu dự phòng cho HS quên đồ dùng.\n- GV nhắc an toàn: dùng kéo cẩn thận, không đùa nghịch khi cầm kéo; keo và màu không đưa lên miệng.","hs":"- HS làm bài độc lập theo các bước và thời gian gợi ý.\n- HS thể hiện rõ hình ảnh chính đúng chủ đề đã chọn.\n- HS tạo đậm nhạt để bài có trọng tâm.\n- HS giữ trật tự, dùng kéo và keo an toàn."},{"ten":"3. Trưng bày, tự đánh giá và đánh giá chéo","gv":"- (8 phút) GV cho HS dán bài lên bảng nhóm theo chủ đề, tạo phòng tranh mini cuối năm ở góc lớp.\n- GV phát phiếu tự đánh giá, hướng dẫn HS đối chiếu bài mình với 4 tiêu chí và đánh dấu mức Đạt hoặc Cần cố gắng.\n- GV cho HS đi xem bài bạn, dán một sao giấy vào bài mình thích và nói theo mẫu \"Mình thích bài này vì...\".\n- GV mời 3-4 HS giới thiệu sản phẩm: chủ đề, hình ảnh chính, chất liệu và điều em hài lòng nhất ở bài mình.","hs":"- HS trưng bày bài ngay ngắn theo nhóm chủ đề.\n- HS tự đánh giá bài mình theo 4 tiêu chí.\n- HS dán sao và nói lời nhận xét theo mẫu câu.\n- HS giới thiệu sản phẩm của mình trước lớp."},{"ten":"4. Vận dụng - Tổng kết, dặn dò","gv":"- (3 phút) GV nhận xét kết quả cả năm theo tiêu chí, ghi nhận sự tiến bộ của từng HS.\n- GV gợi ý vận dụng: chọn 3-5 bài đẹp nhất làm bộ sưu tập cá nhân, dùng trang trí góc học tập hoặc tặng người thân.\n- GV tuyên dương HS chăm chỉ, có ý tưởng riêng và nhóm giữ vệ sinh tốt; nhắc thu giấy vụn, lau bàn, rửa tay.\n- GV dặn HS chọn sản phẩm đẹp nhất trong năm và chuẩn bị cho tiết trưng bày sản phẩm cuối năm.","hs":"- HS lắng nghe nhận xét, nhận ra điều mình đã tiến bộ.\n- HS chọn bài để làm bộ sưu tập cá nhân.\n- HS thu dọn lớp học và rửa tay sạch sẽ.\n- HS ghi nhớ việc chuẩn bị cho tiết trưng bày cuối năm."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Kiểm tra, đánh giá cuối năm học"},
{"lop":5,"mon":"Mĩ thuật","tuan":35,"tiet":35,"bai":"Trưng bày sản phẩm cuối năm và tổng kết năm học","yccd":"1. Năng lực mĩ thuật\n- Lựa chọn, sắp xếp và trưng bày được sản phẩm mĩ thuật tiêu biểu của cả năm học.\n- Giới thiệu, phân tích và nêu được cảm nhận về sản phẩm theo yếu tố, nguyên lí tạo hình.\n- Biết vận dụng kết quả học tập vào trang trí, làm đẹp lớp học và cuộc sống.\n2. Năng lực chung\n- Giao tiếp và hợp tác; giải quyết vấn đề và sáng tạo khi tổ chức trưng bày.\n3. Phẩm chất\n- Yêu thích môn học, trân trọng thành quả lao động; tự tin, đoàn kết, có trách nhiệm.\n4. Tích hợp\n- Năng lực số 3.2 CB2a: Chọn được các cách sửa đổi, tinh chỉnh, cải thiện và tích hợp các mục đơn giản có nội dung và thông tin mới để tạo ra những nội dung và thông tin mới và độc đáo: HS tham gia dựng và hoàn thiện triển lãm số cuối năm của lớp.","dodung":"- Giáo viên: không gian trưng bày, tiêu chí đánh giá; thiết bị trình chiếu học liệu số.\n- Học sinh: các sản phẩm mĩ thuật đã thực hiện trong năm; đồ dùng để trang trí, sắp xếp trưng bày.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, nêu mục đích tiết trưng bày sản phẩm và tổng kết năm học.\n- GV tạo không khí vui tươi, khích lệ HS.","hs":"- HS lắng nghe, hào hứng tham gia."},{"ten":"2. Khám phá - Chuẩn bị trưng bày","gv":"- GV hướng dẫn HS lựa chọn, sắp xếp sản phẩm tiêu biểu của cả năm theo nhóm/chủ đề.\n- GV gợi ý cách trang trí không gian trưng bày đẹp mắt, khoa học.","hs":"- HS lựa chọn, sắp xếp và trang trí sản phẩm.\n- HS chuẩn bị lời giới thiệu cho khu trưng bày."},{"ten":"3. Luyện tập - Trưng bày, giới thiệu","gv":"- GV tổ chức cho HS trưng bày, giới thiệu và thuyết trình về sản phẩm.\n- GV cùng HS thảo luận, bình chọn sản phẩm ấn tượng; nhận xét, đánh giá.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS thảo luận, nhận xét, bình chọn sản phẩm yêu thích."},{"ten":"4. Vận dụng - Tổng kết","gv":"- GV tổng kết năm học, tuyên dương HS có nhiều cố gắng và sáng tạo.\n- GV gợi ý HS tiếp tục vẽ, sáng tạo và làm đẹp cuộc sống trong dịp hè.","hs":"- HS nêu cảm nghĩ về môn học.\n- HS lắng nghe, ghi nhớ và có ý thức tiếp tục sáng tạo mĩ thuật."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) HS cùng nhau dựng triển lãm số cuối cấp tiểu học: chọn sản phẩm tiêu biểu của cả năm, sắp xếp theo chủ đề, viết lời mở đầu cho triển lãm và chú thích cho từng tác phẩm.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 2) HS phân công vai trò người dựng trang, người viết chú thích, người thuyết minh; mỗi nhóm báo cáo phần việc của mình và góp ý cho nhóm bạn.\n⚠ (Miền 4: An toàn) Triển lãm ghi đủ tên tác giả và nguồn tư liệu; chỉ ghi tên và lớp, không đưa số điện thoại, địa chỉ của HS; muốn đăng lên trang của trường phải được nhà trường và cha mẹ đồng ý.","hs":"- HS tham gia dựng và hoàn thiện triển lãm số cuối năm của lớp.\n- HS nhận và hoàn thành được vai trò của mình trong nhóm, góp ý cho nhóm bạn."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Trưng bày sản phẩm cuối năm và tổng kết năm học"}
];
